(function () {
  "use strict";
  var DATA = {"version":"2.1.0","builtAt":"2026-09-02T05:57:19.734Z","curriculum":{"$schema":"AI Knowledge OS · Curriculum v2.0 (Category → Chapter → Lesson → Concept)","note":"四层结构：Category 分类 → Chapter 章 → Lesson 课（真正学习单元）→ Concept（知识图谱最小节点）。134 个 Concept 被组织进约 52 个 Lesson；一个 Lesson 可由多个 Concept 组合而成。此时 Lesson 是学习单位，Concept 是图谱节点。","lessonCount":52,"flagShip":["l00-ai-world","l-attention","l-embedding","l-transformer","l-rag","l-agent"],"categories":[{"category":"c01-ai-world","title":"AI 世界地图","overview":{"headline":"让机器从数据里找到规律","questions":["AI、机器学习、深度学习到底是什么关系？","AI 现在能干什么、不能干什么？","为什么最近几年 AI 突然爆发？","我从哪里开始学起？"],"mentalModel":["数据 Data","模型 Model","预测 Prediction","误差 Loss","梯度 Gradient","参数更新 Update"]},"chapters":[{"title":"第一章 · AI 全景","lessons":[{"id":"l00-ai-world","ready":true,"title":"一张图看懂整个 AI 世界"},{"id":"l01-ai-vs-ml-dl","ready":false,"title":"AI / Machine Learning / Deep Learning 到底什么关系"}]}]},{"category":"c02-essentials","title":"AI 必备基础","overview":{"headline":"看懂 AI 需要的最小数学与概念地基","questions":["文字、图片怎么变成电脑能算的数字？","向量是什么？为什么意思相近的词距离更近？","什么叫梯度，为什么模型靠它学习？","概率和不确定性在 AI 里有什么用？"],"mentalModel":["实体","→ 向量 Vector","→ 向量空间","→ 相似度","→ 学习"]},"chapters":[{"title":"第一章 · 向量与语义","lessons":[{"id":"l-embedding","ready":true,"title":"Embedding｜怎么把词变成电脑能懂的数字"},{"id":"l02-vector-space","ready":false,"title":"向量空间与相似度"}]},{"title":"第二章 · 数学地基","lessons":[{"id":"l03-matrix-gradient","ready":false,"title":"矩阵、函数与梯度入门"},{"id":"l04-probability","ready":false,"title":"概率：AI 在预测什么"}]}]},{"category":"c03-ml","title":"机器学习","overview":{"headline":"让机器从数据里找到规律","questions":["机器到底怎么『学习』？","模型为什么能预测没见过的东西？","模型怎么知道自己错了？","为什么训练效果好，现实里却可能很差？"],"mentalModel":["数据","→ 模型","→ 预测","→ 误差 Loss","→ 梯度 Gradient","→ 参数更新","↺"]},"chapters":[{"title":"第一章 · 学会学习","lessons":[{"id":"l05-gradient-descent","ready":false,"title":"Gradient Descent｜模型怎么『往下走』学会预测"}]},{"title":"第二章 · 预测与评估","lessons":[{"id":"l06-overfitting","ready":false,"title":"为什么训练好、现实差：过拟合"},{"id":"l07-eval","ready":false,"title":"怎么判断模型到底好不好"}]}]},{"category":"c04-dl","title":"深度学习","overview":{"headline":"多层神经网络如何工作","questions":["神经元、层、网络是什么？","反向传播在传什么？","深度为什么有用？"],"mentalModel":["输入","→ 神经元","→ 层","→ 激活","→ 输出","← 反向传播 ← 误差"]},"chapters":[{"title":"第一章 · 神经网络","lessons":[{"id":"l08-neural-network","ready":false,"title":"Neural Network｜神经元如何组成可学习的网络"}]},{"title":"第二章 · 学习机制","lessons":[{"id":"l09-backprop","ready":false,"title":"反向传播：误差如何传回去改参数"},{"id":"l10-cnn-rnn","ready":false,"title":"CNN 与 RNN：两种经典网络在解决什么"}]}]},{"category":"c05-llm","title":"大语言模型","overview":{"headline":"ChatGPT 这类大模型到底在干嘛","questions":["大模型是怎么『学会』说话的？","Transformer 和 Attention 是什么？为什么它颠覆了一切？","上下文窗口、Token、温度是什么意思？","为什么模型会一本正经地胡说八道？"],"mentalModel":["Token","→ Embedding","→ Transformer","→ 生成下一个词","→ 上下文","→ 输出"]},"chapters":[{"title":"第一章 · 语言如何进入模型","lessons":[{"id":"l11-tokenization","ready":false,"title":"Tokenization｜LLM 是怎么『读』文字的"},{"id":"l12-context-window","ready":false,"title":"上下文窗口：模型一次能『看见』多少"}]},{"title":"第二章 · Transformer","lessons":[{"id":"l-transformer","ready":true,"title":"Transformer｜大模型的地基架构"},{"id":"l-attention","ready":true,"title":"Attention｜模型为什么知道该关注哪个词"}]},{"title":"第三章 · 训练与推理","lessons":[{"id":"l13-llm-training","ready":false,"title":"预训练 / 微调 / RLHF"},{"id":"l14-inference","ready":false,"title":"推理：模型如何生成一个词一个词地说话"},{"id":"l15-prompt","ready":false,"title":"Prompt 工程：怎么和模型说清楚"}]}]},{"category":"c06-llm-app","title":"LLM 应用","overview":{"headline":"把大模型接进真实产品","questions":["怎么调用一个模型做出产品？","函数调用、结构化输出、流式是什么？","怎么评估一个 AI 功能做得好不好？"],"mentalModel":["用户输入","→ API","→ 模型","→ 输出","→ 评估"]},"chapters":[{"title":"第一章 · 接入模型","lessons":[{"id":"l16-llm-api","ready":false,"title":"用 API 把模型接进你的产品"},{"id":"l17-function-calling","ready":false,"title":"Function Calling｜让模型能『动手』"}]}]},{"category":"c07-rag","title":"RAG 检索增强","overview":{"headline":"让模型基于你的资料回答","questions":["模型记不住我的私有资料，怎么办？","RAG 是怎么『找到』相关内容的？","RAG 和微调有什么不同？"],"mentalModel":["文档","→ 切块 Chunk","→ 向量化","→ 检索","→ 上下文","→ 生成"]},"chapters":[{"title":"第一章 · RAG 全流程","lessons":[{"id":"l-rag","ready":true,"title":"RAG｜让模型『查资料』再回答"}]}]},{"category":"c08-agent","title":"Agent 智能体","overview":{"headline":"让 AI 从『回答』到『做事』","questions":["为什么 ChatGPT 不能帮我们操作电脑，Codex 却可以？","Agent 和普通聊天机器人差在哪？","Agent 怎么用工具、怎么规划、怎么循环？"],"mentalModel":["目标","→ 推理","→ 调用工具","→ 观察结果","→ 下一步","↺"]},"chapters":[{"title":"第一章 · 从会说到会做","lessons":[{"id":"l-agent","ready":true,"title":"Agent｜让 AI 自己动手做事"}]}]},{"category":"c09-multimodal","title":"多模态","overview":{"headline":"让 AI 看得见、听得见、能生成","questions":["AI 怎么『看懂』图片和视频？","声音、图像、文字怎么在一个模型里对齐？","扩散模型怎么生成图片？"],"mentalModel":["图像","→ 编码","→ 对齐","→ 生成"]},"chapters":[{"title":"第一章 · 多模态基础","lessons":[{"id":"l18-multimodal","ready":false,"title":"多模态｜AI 如何同时理解文字、图片、声音"},{"id":"l19-diffusion","ready":false,"title":"Diffusion｜图片是怎么被『画』出来的"}]}]},{"category":"c10-ai-eng","title":"AI 工程","overview":{"headline":"把 AI 系统做进生产环境","questions":["一个 AI 应用上线要做什么？","成本、延迟、评估怎么管理？","向量数据库、评估、框架怎么选？"],"mentalModel":["需求","→ 选型","→ 构建","→ 评估","→ 上线","→ 监控"]},"chapters":[{"title":"第一章 · 工程化","lessons":[{"id":"l20-ai-eng","ready":false,"title":"AI 工程：从原型到生产"},{"id":"l21-eval-cost","ready":false,"title":"评估与成本：怎么判断值不值"}]}]},{"category":"c11-ai-coding","title":"AI 编程","overview":{"headline":"用 AI 大幅提升编码效率","questions":["AI 结对编程怎么用？","Agentic Coding 和补全有什么不同？","上下文工程怎么让 AI 更懂你的代码库？"],"mentalModel":["需求","→ 上下文","→ AI 生成","→ 审查","→ 迭代"]},"chapters":[{"title":"第一章 · AI Coding","lessons":[{"id":"l22-ai-coding","ready":false,"title":"AI Coding｜把 AI 变成你的结对程序员"}]}]},{"category":"c12-ai-product","title":"AI 产品与商业","overview":{"headline":"判断一个 AI 产品值不值得做","questions":["一个 AI 产品『技术上能不能做』怎么判断？","AI 产品怎么创造真实价值？","合规、伦理、成本怎么权衡？"],"mentalModel":["用户问题","→ AI 能力","→ 产品形态","→ 价值","→ 商业模式"]},"chapters":[{"title":"第一章 · 产品思维","lessons":[{"id":"l23-ai-product","ready":false,"title":"AI 产品：从想法到落地"}]}]}]},"lessonCount":6,"flagship":["l00-ai-world","l-attention","l-embedding","l-transformer","l-rag","l-agent"],"lessons":{"l00-ai-world":{"id":"l00-ai-world","title":"一张图看懂整个 AI 世界","subtitle":"在学任何一个概念之前，先拿到整张地图：你现在站的哪里，接下来要走到哪里。","category":"c01-ai-world","chapterTitle":"第一章 · AI 全景","level":"base","estTime":"10-15 分钟","difficulty":1,"concepts":["ai-what","ai-ml-dl","ai-apps","ai-limits"],"prereqLessons":[],"nextLesson":"l01-ai-vs-ml-dl","sections":[{"type":"oneline","text":"AI（人工智能）是一整片森林；机器学习是其中会『自己从数据里找规律』的那片树；深度学习是最能长的那几棵；大语言模型（LLM）是最近最抢眼、能和你聊天的那一棵。"},{"type":"why","before":"在你被一大堆名词淹没之前，先停下来。Token、Attention、RAG、Agent……如果不知道它们各自站在地图的哪个位置，学一个忘一个。","problem":"很多初学者的问题不是『不够努力』，而是没有地图：他不知道现在学的东西，将来会连到哪里。","need":"所以第一节课我们不讲细节，只画一张总地图，让你知道：整个 AI 世界的骨架是什么，你将来要学的每一块长在哪里。","visualNote":"下面这张图就是你要带走的『世界地图』。"},{"type":"visual","kind":"ai-world-map","title":"AI 世界全景图","hint":"从最外层的 AI 一路往内收缩到 LLM；再往外展开 Vision / Speech / Agent / RAG 等应用方向。点击你能看懂就往下一层。"},{"type":"intuition","blocks":[{"k":"用一棵树来想","t":"把 AI 想成一棵树：树干是『机器学习』——所有『机器自己学』的方法都从这儿长出来；从树干分出的粗枝是『深度学习』；深度学习上最茂密的一枝长出了『大语言模型』。你平时用的 ChatGPT 只是这棵树上的一颗果实。"},{"k":"用俄罗斯套娃来想","t":"AI 是最大的套娃，Machine Learning 是里面一层，Deep Learning 再里面一层，LLM 是最小最精致的那层。每往里一层，都建立在外层之上。"},{"k":"一句话总结链条","t":"AI ⊃ Machine Learning ⊃ Deep Learning ⊃ Foundation Model ⊃ LLM。这一个箭头链条，就是整张地图的主干。"}]},{"type":"how","intro":"把整张地图拆成一个从内到外、再到应用的主干流程，你学完至少知道每块知识的归属。","steps":[{"in":"AI（人工智能）","process":"最上层总称：让机器表现出智能的一切技术。","out":"范围最大，包含规则、搜索、机器学习等"},{"in":"Machine Learning","process":"机器从数据里自动找规律，而不是人写死规则。","out":"监督 / 无监督 / 强化学习 三大流派"},{"in":"Deep Learning","process":"用『多层神经网络』来学习，能力更强的机器学习子集。","out":"CNN、RNN、Transformer 等网络结构"},{"in":"Foundation Model（基础模型）","process":"在大规模数据上预训练好的通用模型，可以微调复用到很多任务。","out":"LLM（语言）、视觉模型、多模态模型"},{"in":"LLM（大语言模型）","process":"以『预测下一个词』为核心任务训练出来的大模型，学会了语言与世界知识。","out":"ChatGPT、Claude、Gemini 的前身"},{"in":"围绕 LLM 的应用层","process":"为了让模型更好用，叠加外围技术。","out":"Prompt 提示、RAG 检索、Agent 智能体、多模态"}]},{"type":"realworld","items":[{"name":"ChatGPT","note":"纯 LLM 的产品：你打字，它生成下一个词。"},{"name":"Claude / Gemini","note":"同样是 LLM，但被训练得在不同任务上更擅长。"},{"name":"NotebookLM","note":"用 RAG：你上传资料，它『查你给的材料』再回答。"},{"name":"Codex / Claude Code","note":"用 Agent：不只是回答，还会调用工具去改代码、跑命令。"}]},{"type":"compare","pairs":[{"a":"AI","b":"Machine Learning","diff":"AI 是目标（机器有智能）；机器学习是其中一种『用数据学出来』的手段。早期 AI 靠人写规则，也属于 AI。"},{"a":"Machine Learning","b":"Deep Learning","diff":"都是『从数据学习』；深度学习特指用多层神经网络，能自动从数据中提取特征，能力更强。"},{"a":"LLM","b":"Foundation Model","diff":"LLM 是专门做语言的基础模型；Foundation Model 是更大的类：还包括视觉、多模态等。"}]},{"type":"mistakes","items":["把『AI』『机器学习』『深度学习』当同义词——其实是一层层包含关系。","以为 ChatGPT = 整个 AI。它只是 LLM 的一颗果实，AI 世界还有视觉、语音、Agent、机器人等一大堆。","以为学 AI 必须先把所有底层数学都精通。地基课会给你『够用』的数学，不是研究生讲义。"]},{"type":"practice","quiz":[{"q":"下面的包含关系哪一个是正确的？","opts":["AI ⊃ LLM ⊃ Deep Learning ⊃ ML","AI ⊃ ML ⊃ Deep Learning ⊃ LLM","LLM ⊃ AI ⊃ ML ⊃ Deep Learning","Deep Learning ⊃ ML ⊃ AI ⊃ LLM"],"a":1,"explain":"AI 包含机器学习，机器学习包含深度学习，LLM 是深度学习上长出的一个具体模型——所以 AI ⊃ ML ⊃ DL ⊃ LLM。"},{"q":"ChatGPT 更像下面哪一个？","opts":["一个 Agent","一个纯 LLM 对话产品","一个 RAG 系统","一个视觉模型"],"a":1,"explain":"ChatGPT 的核心是大语言模型：你输入，它预测下一个词。RAG/Agent 是在它之上叠加的能力。"},{"q":"NotebookLM『查你上传的资料再回答』，主要用到了哪项技术？","opts":["RAG / 检索增强生成","纯预训练","强化学习","扩散模型"],"a":0,"explain":"针对私有资料，RAG 会让模型先去检索相关片段再做回答，这正是 NotebookLM 类产品的核心。"}]},{"type":"connection","known":["（这是第一节课，还没有前置知识）"],"learned":["AI → ML → DL → LLM 的主干链条","LLM 之外还有视觉 / 语音 / Agent / RAG 等方向","ChatGPT、Claude、Codex、NotebookLM 各自代表哪一类"],"next":"接下来你会先进入『向量与语义』：Embedding 是怎么把文字变成电脑能算的数字——这是理解 LLM 的第一块砖。"}]},"l-embedding":{"id":"l-embedding","title":"Embedding｜怎么把词变成电脑能懂的数字","subtitle":"为什么文字不能直接进神经网络？为什么不是给每个词编个号？为什么意思相近的词离得更近？","category":"c02-essentials","chapterTitle":"第一章 · 向量与语义","level":"base","estTime":"20 分钟","difficulty":2,"concepts":["embedding","vector","cosine-similarity","emb-vector-store"],"prereqLessons":["l00-ai-world"],"nextLesson":"l-attention","sections":[{"type":"oneline","text":"Embedding 就是把『一个词』变成『一串数字（向量）』，并且让意思相近的词，数字串长得也相近——于是电脑就能『算』语义了。"},{"type":"why","before":"神经网络只会做数学运算：加、乘、比较大小。它天生看不懂文字『猫』『狗』『苹果』。","problem":"如果你根本没法把文字送进神经网络，那后面的一切（翻译、对话、理解）都是空中楼阁。这是所有语言模型的『第一道门』。","need":"所以我们必须在文字和数字之间搭一座桥。这座桥就是 Embedding。","visualNote":"先看一个最朴素的思路，再一步步升级到真正的 Embedding。"},{"type":"intuition","blocks":[{"k":"为什么不能直接给词编号？","t":"你可能会想：给猫=1、狗=2、苹果=3 不就行了？但问题是：2 和 3 只差 1，可『狗』和『苹果』的语义差得十万八千里。编号把『数字距离』和『语义距离』完全搞乱了。"},{"k":"用一张坐标纸来想","t":"想象一张二维地图，横轴是『是不是动物』，纵轴是『是不是食物』。『猫』放左边偏上，『狗』放它旁边，『苹果』放右上角。位置越近，意思越像。Embedding 本质就是在几百上千维的『坐标纸』上，给每个词找个位置。"},{"k":"一个生活类比","t":"就像地理坐标：北京和天津坐标很近，所以它们在空间上相邻；Embedding 也是给词一个『语义坐标』，语义相近的词坐标也相邻。"}]},{"type":"visual","kind":"embedding-space","title":"Embedding 2D 语义空间","hint":"这是把词『压扁』到二维的示意：意思相近的词会聚在一起。观察猫/狗/狮子聚在『动物角』，苹果/香蕉聚在『食物角』。"},{"type":"how","intro":"Embedding 是怎么『学』出来的？关键思想：一个词的含义 = 它经常和哪些词一起出现。","steps":[{"in":"收集大量文本","process":"从整个互联网 / 语料库里，观察『猫』总是和『狗、宠物、喵、毛』一起出现，而『苹果』总跟『水果、吃、红色』一起出现。","out":"得到每个词在语料里的『共现模式』"},{"in":"用共现模式训练向量","process":"训练算法会分配一组初始数字，然后不断调整，让『一起出现』的词向量越走越近，『从不一起出现』的词向量越走越远。","out":"每个词最终固定成一个向量（如 300 维数字）"},{"in":"用向量距离比较语义","process":"两个词的向量越接近（夹角越小 / 余弦相似度越高），语义越相近。","out":"电脑就能『算』出：猫≈狗，苹果≠猫"},{"in":"送入下游模型","process":"这个数字向量就是神经网络的输入。LLM 只认数字，现在它『看得懂』词了。","out":"模型能对词做运算、比较、生成"}]},{"type":"deep","beginner":["Embedding 是『查表』：模型里有一张巨大的表，每个词一行，那一行数字就是它的向量。训练好之后，直接用查到的数字。","维度越高，能表达的语义越细腻，但计算越贵。常见几百维就够用。"],"advanced":["向量不只是给每个词一个『标签』，它把语义结构编进了几何里：经典例子 king - man + woman ≈ queen，说明方向也承载意义。","Embedding 模型（如 text-embedding 系列）与 LLM 是不同模型：前者把文本压缩成‘定位码’，后者生成文字。它们可以分开训练、分开使用。",{"code":"# 概念示意：余弦相似度，越大越像\nimport numpy as np\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\ncat = np.array([0.9, 0.1])    # 靠近动物方向\napple = np.array([0.1, 0.9])  # 靠近食物方向\nprint(cosine(cat, apple))     # 结果小，说明语义远","lang":"python"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude","note":"内部第一件事就是把你的每个词 Token 转成 Embedding 向量，再送进 Transformer。"},{"name":"搜索引擎语义检索","note":"把『怎么养猫』和『养宠物指南』都向量化，语义相近就能匹配，不必字面相同。"},{"name":"NotebookLM / RAG","note":"把你的资料切成块并向量化，用户提问时在向量空间里『找最像的那几块』再交给模型回答。"}]},{"type":"compare","pairs":[{"a":"Token","b":"Embedding","diff":"Token 是文字切出的‘小块’（词/子词）；Embedding 是把每个小块变成的‘数字向量’。Token 决定切多细，Embedding 决定怎么算语义。"},{"a":"Embedding 模型","b":"LLM","diff":"Embedding 模型把文本压成‘定位向量’（不做对话）；LLM 生成文字。一个是‘编码员’，一个是‘作家’。"},{"a":"给词编号（One-hot）","b":"Embedding","diff":"编号让所有词距离相等、无法表达语义；Embedding 让相近的词距离更近，真正抓住了含义。"}]},{"type":"mistakes","items":["以为 Embedding 只是『给每个词一个数字』。其实是一整串数字（向量），且数字之间有序的相似关系。","以为 Embedding 模型和 LLM 是一个东西。它们是两个分工不同的模型。","以为向量维度越高一定越好。维度高表达力强但更贵、更易过拟合。","以为 Embedding 能理解逻辑。它只捕捉统计上的‘相似’，不保证逻辑正确。"]},{"type":"practice","quiz":[{"q":"为什么不能直接给每个词编个号（猫=1，狗=2）？","opts":["因为编号会让相近的词距离更近","因为编号会破坏语义距离：狗和苹果只差1，但语义差很远","因为编号需要太多内存","因为编号不能用于神经网络"],"a":1,"explain":"编号把‘数字距离’和‘语义距离’搞混了：只有编号差1的两个词会显得很近，但这和它们的含义无关。"},{"q":"两个 Embedding 向量‘夹角越小’，说明什么？","opts":["两个词的语义越相近","两个词的字符串越像","两个词出现频率越接近","两个词长度越接近"],"a":0,"explain":"夹角越小、余弦相似度越高，代表两个词在向量空间里越近，语义越相近。"},{"q":"关于 Embedding 模型与 LLM，正确的是？","opts":["它们是同一个模型","Embedding 模型把文本变向量，LLM 生成文字，二者分工不同","LLM 不做 Embedding","Embedding 模型能写文章"],"a":1,"explain":"Embedding 模型负责‘编码相似度’，LLM 负责‘生成内容’，是不同的模型。"}],"lab":{"title":"Mini Lab：2D 语义空间","desc":"在上方 Embedding 空间里，给新词拖一个位置，观察它和哪群已知词更近。体会‘位置=语义’这件事。","kind":"embedding-space"}},{"type":"connection","known":["AI 世界全景：模型只能处理数字"],"learned":["文字 → 向量，让电脑能算语义","相近的词向量距离更近，用余弦相似度衡量","Embedding 模型与 LLM 分工不同"],"next":"有了‘每个词是一个数字向量’，下一步就是大招：Attention——模型怎么在一句话里决定‘该重点关注哪个词’。再往前一步，你会看到 Transformer 如何把一堆向量变成会翻译、会聊天的大脑。"}]},"l-attention":{"id":"l-attention","title":"Attention｜模型为什么知道该关注哪个词","subtitle":"当模型读到『它』，怎么知道是猫还是狗？为什么句子再长，模型也能把前后的词『对上号』？","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"20 分钟","difficulty":2,"concepts":["attention","qkv","multihead","attention-long"],"prereqLessons":["l-embedding"],"nextLesson":"l-transformer","sections":[{"type":"oneline","text":"Attention 是这样一种机制：模型在理解某个词时，会『回头看一眼』句子里的每一个词，并给它们分别打一个权重分——分数越高的词，模型花越多『注意力』在它身上。于是『它』到底指猫还是狗，模型有了办法分清。"},{"type":"why","before":"上节课我们把每个词变成了向量。但词是孤立的：『猫』『追』『狗』『它』，每一个都只是单独的一个数字串。","problem":"真正的语言是互相指代的。『猫追狗，它跑得飞快』——这个『它』是谁？只看『它』这个词本身，根本答不上来。更糟的是：以前的模型看长句时，越靠前的词就越『记不清』。","need":"我们需要一个机制：在处理任何一个词时，能直接『回看』整句话里的所有词，按『相关程度』加权吸收它们的信息。这就是 Attention——『注意力』。","visualNote":"下面你可以亲手造一句中文，点任何一个词，看它把注意力分给了谁。"},{"type":"visual","kind":"attention-heatmap","title":"Attention 热力图：点一个词，看它关注谁","hint":"输入一句话，点任意一个词（比如那棵/那株），热力图会显示这个词对其它词的『关注权重』——颜色越深，越关注。体型/量词线索会让权重自动偏向正确的词。"},{"type":"intuition","blocks":[{"k":"老师点名：每个词都是老师","t":"把模型想象成在逐一『审问』句子里的每个词。读到『它』这个词时，模型其实在问：『谁能告诉我『它』指谁？』——它会把问题抛向所有词，然后听答案最相关的那几个。"},{"k":"查字典：不是顺序读，而是跳着看","t":"Attention 最反直觉的一点：它不是老老实实从左往右读。读到『它』，它像翻开一本字典快速扫过所有词条，直接锁定『猫』『跑』这些词，记下『我主要靠这几个词来理解自己』。"},{"k":"聚光灯：每个词都有无数盏灯","t":"句子里每个词都举着一盏聚光灯照向其它词。灯越亮，代表『我理解你时越依赖你』。Attention 就是计算这盏灯亮度的过程。"}]},{"type":"how","intro":"Attention 到底怎么『算』注意力？核心就四步：每个词同时扮演三个角色——Query（我找谁）、Key（我是谁）、Value（我的内容）。","steps":[{"in":"乘上三个矩阵，得到 Q / K / V","process":"每个词的向量，分别乘以三个不同的矩阵，变成三个新向量：Query『我要去匹配谁』、Key『我是谁，请拿我来匹配』、Value『我的有效内容』。","out":"单词 → (Query, Key, Value) 三件套"},{"in":"用 Query 和所有 Key 算相似度","process":"以『它』的 Query 为例，和句子里每个词的 Key 做点积（就是 Embedding 课学过的‘方向越像越接近’）。","out":"得到一个分数列表：它 vs 猫 = 高分，它 vs 跑 = 中等……"},{"in":"Softmax 归一化成权重","process":"把所有分数经过 softmax，变成『加起来等于 100%』的权重。这一步保证了分数变成可比的概率。","out":"注意力权重：猫 0.6、跑 0.25、飞快 0.15……"},{"in":"用权重 × Value 加权求和","process":"把每个词的 Value 乘上它对应的权重再全部相加。权重大的词，它的内容在结果里占的份量就大。","out":"『它』经过处理后的新向量 = 主要吸收了『猫』的信息"},{"in":"每个词同时做，得到上下文向量","process":"句子里每个词都执行同样一套操作，得到一批『结合了全局上下文的新向量』。","out":"整个句子从一串孤立向量 → 一串互相理解的向量"},{"in":"多个头并行（多头注意力）","process":"为了不只从一种角度看，模型并行做多组 Q/K/V（不同随机初始化的矩阵），相当于多个不同视角同时观察。","out":"一个头看‘指代关系’，另一个头看‘语法结构’，再一个看‘长度’……"}]},{"type":"deep","beginner":["注意力权重加起来是 1（100%）。Softmax 就是把一坨分数变成「加起来为 1、且大的更大」的数。","不用纠结矩阵怎么算：你只需要记住『Query 找人，Key 被找，Value 是内容，三者相乘加权求和』这句话。","它最厉害的地方：任意两个词无论隔多远都能直接相关——远处那个词和眼前这个词，算注意力的成本完全一样。"],"advanced":["核心公式：Attention(Q, K, V) = softmax(Q·Kᵀ / √d) · V。除以 √d（d 是向量维度）是为了防止点积过大把 softmax 压死（梯度消失）。","Self-Attention：Q/K/V 都来自同一句话，让句子内部互相理解；Cross-Attention：Q 来自一方，K/V 来自另一方（例如翻译时译文找原文的对应）。","复杂度是 O(n²)：n 个词两两都算一遍。这正是上下文窗口成为瓶颈的原因——也是大家研究稀疏注意力、局部注意力的动机。","不要神化注意力可视化：权重高≠模型真『懂』了。它更多是统计相关，不是可解释的因果。",{"code":"# 概念示意：手工算一次注意力（2 个词的极简版）\nimport math\n\ndef softmax(xs):\n    ex = [math.exp(x) for x in xs]\n    s = sum(ex)\n    return [e / s for e in ex]\n\nq = [1.0, 0.0]  # 我是『它』的 Query\nks = {\"猫\": [0.9, 0.1], \"狗\": [0.2, 0.8]}  # 两个词的 Key\n\nscores = {w: round(q[0]*k[0] + q[1]*k[1], 3) for w, k in ks.items()}\nprint(\"点积分数:\", scores)\nweights = dict(zip(scores, softmax(list(scores.values()))))\nprint(\"softmax 权重:\", {w: round(v,3) for w,v in weights.items()})","lang":"python"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude 生成每个词","note":"每生成一个 token，模型都要对上下文做一次 Attention：决定下一个词『更依赖』前面的哪部分。"},{"name":"翻译模型的对齐","note":"把『I love you』翻译成中文时，Attention 会自动让『love』和『爱』『对上号』，哪怕位置完全错开。"},{"name":"代码补全","note":"模型补全函数体时，Attention 帮它『盯住』几千行前的函数签名和参数定义，而不是只看到最近几行。"},{"name":"长文档问答","note":"你在长文章里问『第三部分的结论是？』，Attention 让模型跳过大段无关内容，直接聚焦第三部分的句子。"}]},{"type":"compare","pairs":[{"a":"RNN 顺序处理","b":"Attention 全局直连","diff":"RNN 必须一个字一个字按顺序传，远处信息会衰减；Attention 任意两个位置直接相联，没有距离衰减。"},{"a":"Self-Attention","b":"Cross-Attention","diff":"Self 是同句话内部互相理解；Cross 是让一方去『读』另一方（翻译、RAG 上下文注入都用它）。"},{"a":"单头注意力","b":"多头注意力","diff":"单头只有一种‘看法’；多头并行多组 Q/K/V，相当于同时用多个角度理解，效果明显更好。"}]},{"type":"mistakes","items":["以为 Attention 是『看一遍就记住』的长期记忆。它不是记忆，而是每次计算时动态分配的关注权重——注意力要重新算，不会存下来。","以为注意力可视化等于模型的可解释性。权重高代表统计上相关，不代表模型逻辑上『是因为这个』。","把『注意力』和『上下文窗口』混为一谈。窗口决定能看多远，Attention 决定窗口内怎么分配关注。","以为只看『最近几个词』。Attention 恰恰是全局的——它牺牲计算量换来的是真正看全上下文。"]},{"type":"practice","quiz":[{"q":"Attention 中，Query、Key、Value 各自的作用最准确的说法是？","opts":["Q 是内容，K 是找人，V 是被找","Q 在找人，K 是被找的标签，V 是被吸收的内容","三者完全相同","Q 是权重，K 是分数，V 是标签"],"a":1,"explain":"Q（Query）发起匹配→去找谁；K（Key）告诉别人『我是谁』、供匹配；V（Value）是被吸收进结果的真正内容。"},{"q":"为什么说 Attention 解决了 RNN『记不住长句』的问题？","opts":["因为它是顺序处理的","因为任意两个词都可以直接相关，不随距离衰减","因为它把句子变短了","因为它只关心最近的词"],"a":1,"explain":"RNN 依赖顺序传递，距离远信息衰减；Attention 让任意两个位置直接相连，远近一视同仁。"},{"q":"把注意力分数做 softmax 是为了？","opts":["让负数变成正数","让分数变成加和为 1 的权重，且强调大的","让计算更快","让向量变短"],"a":1,"explain":"Softmax 把一坨任意分数变成『加起来为 1』、且大者更大的概率分布，这样加权求和才合理。"}],"lab":{"title":"Mini Lab：亲手算一次 Attention","desc":"在上方热力区输入你的一句话，点不同词观察权重分配；再试试把量词改掉，体会权重如何跟着语义线索移动。","kind":"attention-heatmap"}},{"type":"connection","known":["词 → 向量（Embedding）","向量方向越像、语义越近（余弦相似度）"],"learned":["每个词同时是 Query / Key / Value","注意力 = 相似度分数 → softmax 权重 → 加权求和","Self-Attention 让句子内部互相理解，多头提供多视角"],"next":"Attention 是 Transformer 的心脏。下一课我们会看到：怎么把这一套注意力，组装成一个能真正训练、能翻译能写诗的完整大模型架构——Transformer。再往后，你会明白 RAG 和 Agent 都是在这个架构上叠出来的能力。"}]},"l-transformer":{"id":"l-transformer","title":"Transformer｜大模型的地基架构","subtitle":"为什么 2017 年诞生的它，能横扫翻译、写作、代码、对话？一个 20 分钟看懂『大模型的心脏是怎么拼出来的』。","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"25 分钟","difficulty":3,"concepts":["transformer","position-enc","multihead","attention"],"prereqLessons":["l-attention"],"nextLesson":"l-rag","sections":[{"type":"oneline","text":"Transformer 是 2017 年提出的一个『把注意力机制组装成完整大脑』的架构：它用『多头注意力 + 前馈网络 + 残差连接 + 位置编码』堆成一叠一层又一层的模块，能并行、能训练得非常深，从此成为 ChatGPT、Claude、Gemini 的共同地基。"},{"type":"why","before":"上一课我们有了 Attention：任何两个词都能直接互相关注。但这只是一块『积木』，离一个能真正工作的模型还差很远。","problem":"只靠 Attention 还不够：1) 它不知道词的位置——『猫追狗』和『狗追猫』词全一样；2) 一层注意力学到的东西有限；3) 堆深了又容易训练不动。","need":"Transformer 就是给 Attention 配上『位置感、深度、稳定训练的装备』，把一块积木组装成一台可训练的机器。","visualNote":"下面这张图是 Transformer 的主干流水线，你可以一步一步点开看每一层在干什么。"},{"type":"visual","kind":"transformer-flow","title":"Transformer 主干流水线：一步一步看","hint":"点击【下一步】，观察一个词从『数字向量』走到『预测下一个词』的完整过程：输入 → 位置编码 → 多头注意力 → 残差+归一化 → 前馈网络 → 重复堆叠 → 输出。"},{"type":"intuition","blocks":[{"k":"一个加工厂流水线","t":"把 Transformer 想成一家加工厂：原料是一串向量。每个工位（层）做两件事——同事协作（注意力，大家互通信息）＋ 个人精加工（前馈网络，每个词独自想更深）。一层做完送下一层，共 N 层。"},{"k":"用乐高积木来想","t":"Attention 只是其中一块积木。Transformer 是说明书：告诉你『这一层要怎么拼：注意力 + 残差 + 归一化 + 前馈；然后复制粘贴 N 次』。"},{"k":"办公室里的并行会议","t":"RNN 像只有一个话筒的圆桌，每人必须轮流说（慢）；Transformer 像微信群——所有人同时发言、同时收听（并行快），谁跟谁相关自己匹配（注意力）。"}]},{"type":"how","intro":"一个词在 Transformer 里的完整旅程。每一步都围绕同一批向量做变换，最后模型学会『预测下一个词』。","steps":[{"in":"输入：词向量 + 位置编码","process":"每个词先查表得到 Embedding 向量。但向量本身不含『位置』，所以再加一个位置信息（位置编码），让模型知道『这是第 5 个词』。","out":"每个词带上位置的向量"},{"in":"多头注意力层（同事协作）","process":"这一层让每个词结合全局上下文：用上节课的 Q/K/V 机制，多组并行，每组的输出再拼接。词的『含义』从此包含了周围所有词。","out":"每个词变成『理解上下文后的新向量』"},{"in":"残差连接 + 归一化（稳定训练）","process":"把『进来的向量 + 注意力算完的向量』加在一起（残差），再做归一化。这就像修了一条高速公路：信息不衰减地直接流过深层。","out":"浅层信息可以无损‘抄近道’到达深层，网络能堆得深"},{"in":"前馈网络 FFN（个人精加工）","process":"一个两层全连接网络，对每个词独立再做非线性变换，让模型有能力表达更复杂的关系。","out":"每个词被‘再想一想’，表达能力增强"},{"in":"重复堆叠 N 层","process":"把『注意力 + 残差 + 归一化 + 前馈』这组动作复制 N 次叠起来（GPT 有十到上百层）。每层都让词的表示更抽象、更接近任务。","out":"深层的向量已经‘浓缩’了整句话的语义"},{"in":"输出：预测下一个词","process":"最后一层接一个线性层 + softmax，把向量变成『词典里每个词的概率』，模型取概率最高的作为下一个词。","out":"生成一个词 → 拼回输入 → 继续预测下一个词"}]},{"type":"deep","beginner":["位置编码就是给每个词加个『第几个』的记号，否则『猫追狗↔狗追猫』对模型来说字全一样。","残差连接简单说就是『进来和出去加一起』，像搭桥——让深层的梯度不会消失，模型才能堆数十上百层。","前馈网络 FFN 是给每个词单独『换个角度想一遍』，和注意力（词与词协作）分工不同、缺一不可。","GPT 其实只用了 Transformer 的一半：只有『解码器』那套（Decoder-only），用来不停地预测下一个词。"],"advanced":["核心是 Decoder：每个 token 只看自己和前面（因果掩码 causal mask），保证预测时不‘偷看’未来。这是它和编码器最大区别。","缩放点积注意力公式：Attention = softmax(QKᵀ/√d)V。除以 √d 防点积过大导致梯度消失/softmax 饱和。","三种架构：Encoder-only（BERT：理解）、Decoder-only（GPT：生成）、Encoder-Decoder（T5：翻译/转换）。ChatGPT 系清一色 Decoder-only。","残差连接 + LayerNorm（Pre-LN 顺序）是训练稳定性的关键工程细节，是让它能堆到千亿参数的原因之一。","复杂度 O(n²)：上下文窗口越大成本越高——这直接决定了『长上下文为什么贵』『为什么要 RAG』。",{"code":"# 概念示意：位置编码的经典公式（不必实现，体会它想表达什么）\nimport math\n\ndef pos_encoding(pos, d_model=8):\n    # 给第 pos 个词生成 d_model 维的位置向量，奇偶通道分别用 sin/cos\n    vec = []\n    for i in range(d_model):\n        angle = pos / (10000 ** (2 * (i // 2) / d_model))\n        vec.append(round(math.sin(angle), 3) if i % 2 == 0 else round(math.cos(angle), 3))\n    return vec\n\nfor p in [0, 1, 2, 3]:\n    print(f\"第{p}个词的位置: {pos_encoding(p)}\")","lang":"python"}]},{"type":"realworld","items":[{"name":"ChatGPT / GPT 系列","note":"Decoder-only Transformer：单纯地、一层层地预测下一个词，就长出了对话和推理能力。"},{"name":"Claude / Gemini","note":"同一架构的不同工程实现：同样的多头注意力 + 深层堆叠，在尺度与训练技巧上各有差异。"},{"name":"翻译与摘要模型（T5/BART）","note":"Encoder-Decoder 结构：编码器读懂全文，解码器再一句句生成译文或摘要。"},{"name":"代码补全（Codex 前身 CodeGPT）","note":"把代码当‘另一种语言’喂给 Decoder-only Transformer，学会了补全、续写、改 bug。"}]},{"type":"compare","pairs":[{"a":"RNN","b":"Transformer","diff":"RNN 顺序串行、远处信息衰减、难并行；Transformer 全局直连、天然并行、能堆深。2017 后几乎完全取代 RNN。"},{"a":"Encoder-only（BERT）","b":"Decoder-only（GPT）","diff":"前者双向读全文、擅长‘理解’（分类/检索）；后者只能从左往右、擅长‘生成’（对话/写作/代码）。"},{"a":"单层注意力","b":"N 层堆叠的 Transformer","diff":"单层只做一次‘互相看’；Transformer 把多次‘互相看+精加工’叠起来，让表示一层比一层抽象。"}]},{"type":"mistakes","items":["以为『Transformer = Attention』。Attention 只是其中的一个子模块，完整架构还包括残差、归一化、前馈、位置编码。","以为 BERT 和 GPT 一样。BERT 双向理解、GPT 单向生成，职权完全不同。","以为层数越多一定越好。层越深效果提升有边际，还会带来更大的算力和训练难度。","把『位置编码』当可选项。没有它，『猫追狗』和『狗追猫』对模型来说完全一样——这可是天壤之别。"]},{"type":"practice","quiz":[{"q":"为什么 Transformer 需要位置编码？","opts":["为了让向量维度变大","因为注意力本身不含位置信息，没有位置编码『狗追猫』和『猫追狗』无法区分","为了加快计算","为了让训练更快收敛"],"a":1,"explain":"注意力是把所有词互相加权，天然『不记得顺序』；位置编码把‘第几个’注入向量，模型才知道顺序。"},{"q":"残差连接（Residual）的主要作用是？","opts":["增加参数数量","让信息能无损跨层传递，网络可以堆得很深且训练稳定","让模型更快生成","代替位置编码"],"a":1,"explain":"把输入和输出相加，像搭桥一样让信息直达深层，缓解深层网络的梯度消失，是能堆几十上百层的关键。"},{"q":"GPT 属于哪种结构？","opts":["Encoder-only","Decoder-only","Encoder-Decoder","既不是编码器也不是解码器"],"a":1,"explain":"GPT 只用解码器（带因果掩码、从左往右生成），反复预测下一个词。"}],"lab":{"title":"Mini Lab：走一遍 Transformer 流水线","desc":"在上方流水线里逐步播放，观察同一个词每经过一层，它的『表示』如何从字面向量变成富含上下文的向量，最后被用来预测下一个词。","kind":"transformer-flow"}},{"type":"connection","known":["Attention：Q/K/V 加权求和，让词与词互相关注","词是向量，语义可算相似度"],"learned":["Transformer = 多头注意力 + 残差 + 归一化 + 前馈网络的 N 层堆叠","位置编码让模型感知顺序","GPT 是 Decoder-only，靠预测下一个词长出能力"],"next":"Transformer 有了，模型『什么都会但只记得训练时的知识』。下一课我们解决这个关键问题：RAG —— 怎么让模型在回答前先去『你的资料库』查资料，从而回答它没学过的私有内容。"}]},"l-rag":{"id":"l-rag","title":"RAG｜让模型『查资料』再回答","subtitle":"为什么 ChatGPT 不知道你的私有文档？怎么让模型『翻开你的资料』再回答？从切块到生成，一条流水线看懂 RAG。","category":"c07-rag","chapterTitle":"第一章 · RAG 全流程","level":"base","estTime":"25 分钟","difficulty":2,"concepts":["rag-pain","rag-pipeline","chunking","emb-vector-store","vector-search","rerank"],"prereqLessons":["l-transformer","l-embedding"],"nextLesson":"l-agent","sections":[{"type":"oneline","text":"RAG（检索增强生成）就是：让模型在回答之前，先去你的资料库里『检索』相关的内容，把查到的片段拼进上下文，再让模型『照着资料』作答。于是它能回答自己『没学过』的私有知识，还能顺便指出出处。"},{"type":"why","before":"经过前面几课，我们已经有了一个很聪明的模型（Decoder-only Transformer）。但它有一个致命限制：它只知道『训练时见过的东西』，而且经常一本正经地编造（幻觉）。","problem":"1) 你的合同、内部 SOP、论文——模型训练时根本没见过；2) 即使见过，版本也过期了；3) 让它硬答私有问题，它大概率会编。重新训练整个模型又贵又慢。","need":"与其改模型的『脑子』，不如每次回答时给它配一本『说明书』：先把相关的资料找出来喂给它。这个思路就是 RAG，简单、便宜、可随时更新。","visualNote":"下面这条流水线是 RAG 的完整精神：切块 → 向量化 → 检索 → 重排 → 组装 → 生成。你可以一步步看。"},{"type":"visual","kind":"rag-pipeline","title":"RAG 完整流水线：从文档到回答","hint":"逐步播放：上传文档 → 切块 Chunk → 向量化 Embedding → 存入向量库 → 用户提问 → 检索 Top-K → 重排 Rerank → 组装上下文 → 生成回答（带引用）。每一步都点开看细节。"},{"type":"intuition","blocks":[{"k":"开卷考试 vs 闭卷考试","t":"普通 LLM 是闭卷考试：只凭脑子里的记忆答题，记不住就编。RAG 是开卷考试：允许先翻资料，翻到相关的那页再答。显然开卷更可靠。"},{"k":"图书馆查书再回答","t":"你问『公司年假制度是什么』。RAG 不会直接在记忆里编，而是先去公司知识库『检索』年假相关文档，找到后引用着回答。"},{"k":"不是变聪明，是带了参考书","t":"RAG 不提升模型智商，而是每次回答都『带着最新的、属于你的资料』。资料更新，回答立刻跟着更新，不用重新训练。"}]},{"type":"how","intro":"RAG 分两个阶段：『入库』（离线，把文档变成可检索的向量库）和『查询』（在线，用户提问时检索+生成）。下面是完整流程。","steps":[{"in":"为什么需要 RAG（先想清楚）","process":"场景：需要回答私有/最新/超长知识，或需要答案可溯源。如果模型自带答案且内容不敏感，RAG 可能不是最优选。","out":"想清楚：RAG 解决的是『知识更新与私有化』，不是『模型变聪明』"},{"in":"切块 Chunking","process":"把长文档（PDF/网页）切成几百上千字的小块。切多大、是否重叠、按什么切（标题/段落）会直接影响检索质量。","out":"文档 → 若干 chunk（带元数据：来源、页码）"},{"in":"向量化 Embedding","process":"用 Embedding 模型把每个 chunk 变成一个向量（上上节课学的：文字 → 数字，语义相近的向量相近）。","out":"每个 chunk → 一个向量"},{"in":"存入向量库 VectorDB","process":"把『向量 + 原文 + 元数据』一起存进向量数据库（如 FAISS、Milvus、pgvector），并建好索引以便快速搜索。","out":"可毫秒级完成相似检索的向量库"},{"in":"检索 Retrieval","process":"用户提问时，把问题也向量化，然后在向量库里找『最像的 Top-K 块』（一般是余弦相似度排名）。","out":"问题 → 找出最相关的 N 个 chunk"},{"in":"重排序 Rerank","process":"初筛的 Top-K 可能不够准。用一个更精细的模型把这 K 个再排一次，把真正相关的提到最前、过滤掉噪音。","out":"更精准的候选（通常是前 3~5 块）"},{"in":"组装上下文","process":"把检索到的 chunks 拼进 Prompt，附上用户问题，并提示模型『只依据下面的资料回答，引用出处』。","out":"一份带参考资料的完整 Prompt"},{"in":"生成 Generation","process":"LLM 基于这份『资料 + 问题』生成回答，并标注引用了哪一段。","out":"有出处、可更新、针对私有知识的回答"}]},{"type":"deep","beginner":["chunk 太小：语义不完整；chunk 太大：噪音多、还可能被截断。常见几百~一千字 + 20% 重叠。","向量相似≠字面相似：改个说法（『年假』 vs 『带薪假期』）有时也能检索到，这是向量检索比关键词厉害的地方。","RAG 不会凭空创新知识，它只会『引用你给的东西』——所以资料库质量≈回答质量。"],"advanced":["混合检索（Hybrid）：向量检索（语义）+ 关键词检索（BM25，精确匹配人名/编号）结合起来，互补漏检。","Rerank 为什么必要：初检向量健壮但不够精，专门的 rerank 模型（cross-encoder）能逐对精判相关性，显著提升准确率。","引用溯源（Citation / Grounding）：让模型输出时带上片段编号，用户能核对来源，也是落地合规的关键。","GraphRAG 等进阶：把实体关系建成图结构检索，适合『要跨多个文档推理』的难题。","评估：召回率（该找到的找到没）与准确率（找到的是不是都相关），以及最终回答的有据率。",{"code":"# 概念示意：RAG 里最核心的一步——向量检索（伪代码思路）\nimport numpy as np\n\n# 假设我们已经把文档块向量化并存在 chunks 里\nchunks = [\"年假制度：入职满一年享 5 天…\", \"报销流程：金额低于 1000 走 OA…\"]\nchunk_vecs = [np.array([0.9, 0.1]), np.array([0.1, 0.9])]  # 示意向量\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\nquery_vec = np.array([0.85, 0.15])  # 用户问题『年假有几天』向量化\nscores = sorted(((cosine(query_vec, v), i) for i, v in enumerate(chunk_vecs)), reverse=True)\ntop1 = chunks[scores[0][1]]\nprint('最相关的资料块:', top1)  # → 年假制度那一段","lang":"python"}]},{"type":"realworld","items":[{"name":"NotebookLM","note":"你上传 PDF/视频，它检索你的资料再回答，还能生成带引用的播客、摘要。教科书级 RAG 产品。"},{"name":"企业内部知识库客服","note":"把 SOP、产品手册向量化，客服 AI『查文档再回答』，而不是对着空气编。"},{"name":"Claude Projects / 附件上传","note":"给对话挂上资料，模型按需检索引用，本质是一套轻量 RAG。"},{"name":"搜索增强的 ChatGPT / Perplexity","note":"它先联网检索实时网页，再基于检索结果回答——也是 RAG（用 web 当『向量库』）。"}]},{"type":"compare","pairs":[{"a":"RAG","b":"微调 Fine-tuning","diff":"RAG 每次查最新资料、可溯源、便宜、可随时更新；微调是改模型‘脑子’、更像学风格学格式。知识类更新首选 RAG。"},{"a":"向量检索","b":"关键词检索","diff":"向量找‘语义相近’（换个说法也能找到）；关键词精准匹配字面（找人名编号更稳）。生产常用混合。"},{"a":"RAG","b":"超长上下文","diff":"RAG 主动挑最相关片段、便宜快速；超长上下文把整本书塞进去、贵且容易‘淹没’重点。大库优先 RAG。"}]},{"type":"mistakes","items":["以为 RAG = 把文档一股脑塞进提示词。真正的 RAG 要先切块、向量化、检索、重排，只喂最相关的几块。","忽略 chunking 质量。切坏了，再好的模型也答不准——检索进来自的都是垃圾。","以为检索到就完了，不做 rerank。初检的 Top-K 常有噪音，重排能明显提高准确率。","忘记引用溯源。落地到严肃场景（医疗/法务/企业），没有出处等于不可信。","把 RAG 当成解决幻觉的万灵药。资料里没有或检索失败时，模型照样可能编。"]},{"type":"practice","quiz":[{"q":"RAG 解决的核心问题是？","opts":["让模型数学更好","让模型能回答私有/最新知识并可溯源，而不用重新训练","让模型更快生成","让模型学会编程"],"a":1,"explain":"RAG 的核心价值：用检索到的外部资料补充模型没学过的知识，便宜、可更新、可引用。"},{"q":"RAG 的『入库』阶段，正确的顺序是？","opts":["向量化 → 切块 → 存库","切块 → 向量化 → 存库","存库 → 向量化 → 切块","检索 → 切块 → 向量化"],"a":1,"explain":"先把长文档切成 chunk，再逐块向量化，最后连向量带原文存进向量库。『检索』是查询阶段的事。"},{"q":"为什么生产系统里还要做 Rerank 重排？","opts":["为了多花一点算力","初检的 Top-K 常有噪音，用更精细的模型重排能显著提升相关性与准确率","为了把回答变长","为了跳过 embedding"],"a":1,"explain":"向量初检健壮但不精，专门的 rerank 模型能逐对精判，把真正的相关片段提到最前。"}],"lab":{"title":"Mini Lab：走一遍 RAG 全流程","desc":"在上方流水线逐步播放：看一份文档如何被切块、向量化、检索、重排，最终变成一次带引用的回答。理解每一步在哪犯了错会怎样。","kind":"rag-pipeline"}},{"type":"connection","known":["Embedding：文字 → 向量，语义相近的向量相近","Transformer：模型的‘脑子’","上下文窗口：模型一次能看多少"],"learned":["RAG 让模型先检索资料再回答，解决私有/最新/可溯源","完整流程：切块 → 向量化 → 向量库 → 检索 → 重排 → 生成","RAG vs 微调 vs 长上下文 的取舍"],"next":"RAG 让模型『会查资料』，但模型还是停在『你说一句、它应一句』。下一课是这个旅程的终点也是新起点：Agent —— 让模型自己拆目标、自己动手调用工具，把一整件事做完。"}]},"l-agent":{"id":"l-agent","title":"Agent｜让 AI 自己动手做事","subtitle":"为什么 ChatGPT 只能在对话框里打字，而 Codex 能改你的代码、跑你的测试、提交 PR？Agent 就是把『会说话』的模型，变成『会做事』的执行者。","category":"c08-agent","chapterTitle":"第一章 · 从会说到会做","level":"base","estTime":"25 分钟","difficulty":2,"concepts":["agent-intro","agent-loop","tool-use","agent-planning","agent-memory","agent-reflection"],"prereqLessons":["l-rag","l-transformer"],"nextLesson":"l22-ai-coding","sections":[{"type":"oneline","text":"Agent（智能体）不是换个厉害的模型，而是给模型装上一个『决策循环』：它会自己拆目标、自己调用工具（读写文件、执行代码、搜网页）、观察结果、再决定下一步，如此循环直到把事情做完。同样一个模型，套上这个循环，就从『只会回答』变成了『会做事』。"},{"type":"why","before":"到这一课，我们有了很聪明的模型、也有了让它『查资料』的 RAG。但你还是有个困扰：让 ChatGPT 整理个表格它倒是能，让它『去我仓库里改掉那个 bug』，它做不到。","problem":"因为聊天模型只有一张『嘴』：它只能输出文字，看不见你的文件、读不了你的代码、跑不了测试命令。你让它『操作仓库』，它连仓库在哪都不知道。","need":"Model（思考）+ Tools（手和眼）+ Loop（循环驱动）= Agent。它想一下 → 动一下 → 看一眼结果 → 再想 → 再动。这就是 ChatGPT 和 Codex 的分水岭。","visualNote":"下面这个循环图就是 Agent 的灵魂——你可以点每一步看它到底在干什么。"},{"type":"visual","kind":"agent-loop","title":"Agent 循环：想 → 做 → 看 → 再想","hint":"逐步播放一个 Agent 修复 bug 的完整循环：理解目标 → 拆计划 → 调用工具（读代码/改代码/跑测试）→ 观察结果 → 陷入失败 → 修正 → 完成并交付。"},{"type":"intuition","blocks":[{"k":"计算器只会算，助理会办事","t":"普通聊天模型像一台高级计算器：你问它答。Agent 像你的助理：你交代一件事，它自己拆步骤、打电话（调工具）、核对结果，办完给你汇报。"},{"k":"不是变聪明，是变『能动』","t":"它没有比 ChatGPT 更聪明——它只是多了一圈『能动手、能看反馈、能再试』的回路。代码还是那个代码，差别在于它学会了『执行-反馈-调整』。"},{"k":"交给你手里没钥匙的实习生 vs 有钥匙的实习生","t":"ChatGPT 是没钥匙的实习生：看到门（需要改文件）只会描述『你应该去改那个文件』。Agent 是有钥匙的实习生：自己开门、改文件、跑测试、看结果、再改。"}]},{"type":"how","intro":"一个 Agent 改 bug 的完整工作过程。核心就一句话：目标 → 循环（想 + 做 + 看）→ 交付。","steps":[{"in":"理解目标","process":"用户下达：『修好注册页面的 bug』。模型先把模糊目标翻译成具体子任务列表。","out":"一个可执行的任务清单"},{"in":"规划 Planning","process":"它推理出步骤：先找到注册页代码 → 读源码定位问题 → 想怎么改 → 改 → 跑测试验证。","out":"Agenda：找代码 / 读 / 改 / 测"},{"in":"调用工具 Tool Use（Act）","process":"它请求调用工具：read_file 读代码、edit_file 修改、run_command 跑测试。工具返回结果。","out":"一次具体的‘动手’"},{"in":"观察结果 Observe","process":"看到工具返回值：测试报错，或编译失败。它读到反馈，判断是否达到目标。","out":"对‘刚才做的事情对不对’的感知"},{"in":"循环 Loop：再想再做","process":"若未达成，回到‘想’：根据报错调整方案，再调用工具。如此循环直到测试通过或放弃。","out":"反复的 agent loop（这正是和 ChatGPT 的本质区别）"},{"in":"交付与汇报","process":"任务完成：向用户总结改了什么、测试结果，甚至主动提交 PR、申请权限。","out":"一件完成的事，而不是一段话"}]},{"type":"deep","beginner":["Agent Loop 不是魔法：本质就是模型的 for/while 循环——决定下一步 → 调用工具 → 看结果 → 决定再下一步。","工具（Tool）就是『一个函数』：read_file、write_file、run_command、web_search。模型学会了在合适时机调用它们。","最朴素的 Agent = LLM + 工具集 + 一个决定何时停止的循环。它也可以有记忆和规划，但核心就是这个循环。"],"advanced":["Tool Use / Function Calling：模型输出结构化的『要调用哪个函数、传什么参数』，由系统执行并把结果喂回去，形成闭环。","记忆分两层：短期（当前任务的对话/工具历史）与长期（跨对话的项目知识、偏好，常存向量库）。","Planning 范式：ReAct（Reason + Act 交替）、Plan-and-Execute（先定计划再逐步执行、plan 可被动态修订）。","权限与安全 Permission：Agent 不会无限乱来——危险操作（删文件、花钱、外发数据）要求用户授权（approval gate）。","MCP（Model Context Protocol）：统一『工具/数据源』接入协议，让一个 Agent 能标准化接入文件系统、数据库、浏览器等多种工具，避免每家写一套私有接口。","Reflection 反思：让 Agent 回顾刚才失败的原因再调整，显著提升长任务的可靠性。多 Agent 协作则是多个专业 Agent 分工。",{"code":"# 概念示意：Agent 循环的骨架，就长这样\nwhile not goal_reached:\n    thought = model.think(state, memory)      # 想：我要做哪一步？\n    if thought.should_stop: break              # 判断是否完成\n    tool_result = call_tool(thought.tool_call) # 做：调用工具\n    state.append(tool_result)                  # 看：把结果存进上下文\n    memory.update(state)                       # 记住教训\n# 交付\nreport(model.summarize(state))","lang":"python"}]},{"type":"realworld","items":[{"name":"Codex / Claude Code","note":"Agentic Coding 的典型：能读你的仓库、找 bug、改代码、跑测试、提交 PR。这就是『ChatGPT 做不到、它做得到』的原因——它装了代码工具 + agent loop。"},{"name":"Cursor / Windsurf","note":"IDE 里的 Agent：理解整个项目上下文，跨多个文件完成重构，而不只是一行行补全。"},{"name":"浏览器 Agent（如 Browser Use / Operator）","note":"自己打开网页、读取、点击、填表，把『逛网页办事』自动化。"},{"name":"n8n / 工作流编排","note":"让 Agent 串联多个工具/API 完成端到端业务流程（取数→处理→发通知）。"}]},{"type":"compare","pairs":[{"a":"Chatbot（聊天机器人）","b":"Agent（智能体）","diff":"Chatbot 只输出文字、终结于回答；Agent 拆目标、调工具、看结果、循环迭代，终结于『做成事』。"},{"a":"单次工具调用","b":"多步 Agent Loop","diff":"可以调一个工具的助手只是初级；真正的 Agent 会根据结果决定下一调用，持续多轮直到完成。"},{"a":"RPA（脚本化机器人）","b":"LLM Agent","diff":"RPA 按写死的剧本执行、一变就崩；Agent 动态推理、能处理没见过的异常情况。"}]},{"type":"mistakes","items":["以为 Agent 只是『换了个更聪明的模型』。本质差别在『循环 + 工具』，不是模型本身。","以为 Agent 能无限可靠地自主执行。它也会反复失败、会犯错，所以需要权限门槛（approval gate）、观测和护栏。","忽视权限与安全。放任 Agent 删文件/发数据/花钱是最危险的坑，生产环境必须加授权与审计。","把『会调用工具』当成『有规划和反思』。会调一个函数 ≠ 会拆解复杂目标并自我修正，后者才是 Agent 的进阶。","以为多 Agent 一定更好。多数场景单 Agent 更简单可控，盲目堆 Agent 只会带来编排复杂度和成本。"]},{"type":"practice","quiz":[{"q":"为什么 ChatGPT 不能操作你的仓库，而 Codex 可以？","opts":["因为 Codex 模型更聪明","因为 Codex 被接上了工具（读写文件/跑命令）+ Agent 循环，ChatGPT 只有对话输出","因为 ChatGPT 没联网","因为模型大小不同"],"a":1,"explain":"决定性差异不是模型智能，而是 Agent 结构：工具让它可以『动手』，循环让它能『做→看→修正』直到完成。"},{"q":"Agent Loop 的核心循环顺序是？","opts":["看 → 做 → 想","想 → 做 → 看 → 再想","只做不看不回头","想 → 想 → 想"],"a":1,"explain":"标准 agent loop：决定下一步（想）→ 调用工具（做）→ 观察结果（看）→ 根据结果再决定下一步（再想），循环到目标达成。"},{"q":"MCP（Model Context Protocol）主要解决什么问题？","opts":["让模型跑得更快","统一 Agent 接入工具/数据源的接口标准，避免各家用私有协议","代替向量数据库","让模型更聪明"],"a":1,"explain":"MCP 是 Agent 与文件、数据库、浏览器等外部工具的标准化接入协议，一次接入、到处复用。"}],"lab":{"title":"Mini Lab：跑一次 Agent 循环","desc":"在上方循环图里，设一个任务（修 bug / 发邮件 / 整理数据），观察 Agent 每轮『想什么、调哪个工具、看到什么结果』，直到完成或需要你授权。","kind":"agent-loop"}},{"type":"connection","known":["Transformer：模型怎么生成内容","RAG：怎么让模型查资料","工具调用 Function Calling"],"learned":["Agent = 模型 + 工具 + 循环（想→做→看→再想）","它能拆目标、规划、调用工具、观察反馈、反复修正","关键工程点：Tool Use / Memory / Planning / Permission / MCP"],"next":"到这里，你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。想继续深入，建议顺着你的目标分支走：做产品学 LLM 应用与 RAG，写代码就进入 AI 编程（Agentic Coding / Claude Code）那一章。"}]}},"byId":{"l00-ai-world":{"id":"l00-ai-world","title":"一张图看懂整个 AI 世界","subtitle":"在学任何一个概念之前，先拿到整张地图：你现在站的哪里，接下来要走到哪里。","category":"c01-ai-world","chapterTitle":"第一章 · AI 全景","level":"base","estTime":"10-15 分钟","difficulty":1,"concepts":["ai-what","ai-ml-dl","ai-apps","ai-limits"],"prereqLessons":[],"nextLesson":"l01-ai-vs-ml-dl","sections":[{"type":"oneline","text":"AI（人工智能）是一整片森林；机器学习是其中会『自己从数据里找规律』的那片树；深度学习是最能长的那几棵；大语言模型（LLM）是最近最抢眼、能和你聊天的那一棵。"},{"type":"why","before":"在你被一大堆名词淹没之前，先停下来。Token、Attention、RAG、Agent……如果不知道它们各自站在地图的哪个位置，学一个忘一个。","problem":"很多初学者的问题不是『不够努力』，而是没有地图：他不知道现在学的东西，将来会连到哪里。","need":"所以第一节课我们不讲细节，只画一张总地图，让你知道：整个 AI 世界的骨架是什么，你将来要学的每一块长在哪里。","visualNote":"下面这张图就是你要带走的『世界地图』。"},{"type":"visual","kind":"ai-world-map","title":"AI 世界全景图","hint":"从最外层的 AI 一路往内收缩到 LLM；再往外展开 Vision / Speech / Agent / RAG 等应用方向。点击你能看懂就往下一层。"},{"type":"intuition","blocks":[{"k":"用一棵树来想","t":"把 AI 想成一棵树：树干是『机器学习』——所有『机器自己学』的方法都从这儿长出来；从树干分出的粗枝是『深度学习』；深度学习上最茂密的一枝长出了『大语言模型』。你平时用的 ChatGPT 只是这棵树上的一颗果实。"},{"k":"用俄罗斯套娃来想","t":"AI 是最大的套娃，Machine Learning 是里面一层，Deep Learning 再里面一层，LLM 是最小最精致的那层。每往里一层，都建立在外层之上。"},{"k":"一句话总结链条","t":"AI ⊃ Machine Learning ⊃ Deep Learning ⊃ Foundation Model ⊃ LLM。这一个箭头链条，就是整张地图的主干。"}]},{"type":"how","intro":"把整张地图拆成一个从内到外、再到应用的主干流程，你学完至少知道每块知识的归属。","steps":[{"in":"AI（人工智能）","process":"最上层总称：让机器表现出智能的一切技术。","out":"范围最大，包含规则、搜索、机器学习等"},{"in":"Machine Learning","process":"机器从数据里自动找规律，而不是人写死规则。","out":"监督 / 无监督 / 强化学习 三大流派"},{"in":"Deep Learning","process":"用『多层神经网络』来学习，能力更强的机器学习子集。","out":"CNN、RNN、Transformer 等网络结构"},{"in":"Foundation Model（基础模型）","process":"在大规模数据上预训练好的通用模型，可以微调复用到很多任务。","out":"LLM（语言）、视觉模型、多模态模型"},{"in":"LLM（大语言模型）","process":"以『预测下一个词』为核心任务训练出来的大模型，学会了语言与世界知识。","out":"ChatGPT、Claude、Gemini 的前身"},{"in":"围绕 LLM 的应用层","process":"为了让模型更好用，叠加外围技术。","out":"Prompt 提示、RAG 检索、Agent 智能体、多模态"}]},{"type":"realworld","items":[{"name":"ChatGPT","note":"纯 LLM 的产品：你打字，它生成下一个词。"},{"name":"Claude / Gemini","note":"同样是 LLM，但被训练得在不同任务上更擅长。"},{"name":"NotebookLM","note":"用 RAG：你上传资料，它『查你给的材料』再回答。"},{"name":"Codex / Claude Code","note":"用 Agent：不只是回答，还会调用工具去改代码、跑命令。"}]},{"type":"compare","pairs":[{"a":"AI","b":"Machine Learning","diff":"AI 是目标（机器有智能）；机器学习是其中一种『用数据学出来』的手段。早期 AI 靠人写规则，也属于 AI。"},{"a":"Machine Learning","b":"Deep Learning","diff":"都是『从数据学习』；深度学习特指用多层神经网络，能自动从数据中提取特征，能力更强。"},{"a":"LLM","b":"Foundation Model","diff":"LLM 是专门做语言的基础模型；Foundation Model 是更大的类：还包括视觉、多模态等。"}]},{"type":"mistakes","items":["把『AI』『机器学习』『深度学习』当同义词——其实是一层层包含关系。","以为 ChatGPT = 整个 AI。它只是 LLM 的一颗果实，AI 世界还有视觉、语音、Agent、机器人等一大堆。","以为学 AI 必须先把所有底层数学都精通。地基课会给你『够用』的数学，不是研究生讲义。"]},{"type":"practice","quiz":[{"q":"下面的包含关系哪一个是正确的？","opts":["AI ⊃ LLM ⊃ Deep Learning ⊃ ML","AI ⊃ ML ⊃ Deep Learning ⊃ LLM","LLM ⊃ AI ⊃ ML ⊃ Deep Learning","Deep Learning ⊃ ML ⊃ AI ⊃ LLM"],"a":1,"explain":"AI 包含机器学习，机器学习包含深度学习，LLM 是深度学习上长出的一个具体模型——所以 AI ⊃ ML ⊃ DL ⊃ LLM。"},{"q":"ChatGPT 更像下面哪一个？","opts":["一个 Agent","一个纯 LLM 对话产品","一个 RAG 系统","一个视觉模型"],"a":1,"explain":"ChatGPT 的核心是大语言模型：你输入，它预测下一个词。RAG/Agent 是在它之上叠加的能力。"},{"q":"NotebookLM『查你上传的资料再回答』，主要用到了哪项技术？","opts":["RAG / 检索增强生成","纯预训练","强化学习","扩散模型"],"a":0,"explain":"针对私有资料，RAG 会让模型先去检索相关片段再做回答，这正是 NotebookLM 类产品的核心。"}]},{"type":"connection","known":["（这是第一节课，还没有前置知识）"],"learned":["AI → ML → DL → LLM 的主干链条","LLM 之外还有视觉 / 语音 / Agent / RAG 等方向","ChatGPT、Claude、Codex、NotebookLM 各自代表哪一类"],"next":"接下来你会先进入『向量与语义』：Embedding 是怎么把文字变成电脑能算的数字——这是理解 LLM 的第一块砖。"}]},"l-embedding":{"id":"l-embedding","title":"Embedding｜怎么把词变成电脑能懂的数字","subtitle":"为什么文字不能直接进神经网络？为什么不是给每个词编个号？为什么意思相近的词离得更近？","category":"c02-essentials","chapterTitle":"第一章 · 向量与语义","level":"base","estTime":"20 分钟","difficulty":2,"concepts":["embedding","vector","cosine-similarity","emb-vector-store"],"prereqLessons":["l00-ai-world"],"nextLesson":"l-attention","sections":[{"type":"oneline","text":"Embedding 就是把『一个词』变成『一串数字（向量）』，并且让意思相近的词，数字串长得也相近——于是电脑就能『算』语义了。"},{"type":"why","before":"神经网络只会做数学运算：加、乘、比较大小。它天生看不懂文字『猫』『狗』『苹果』。","problem":"如果你根本没法把文字送进神经网络，那后面的一切（翻译、对话、理解）都是空中楼阁。这是所有语言模型的『第一道门』。","need":"所以我们必须在文字和数字之间搭一座桥。这座桥就是 Embedding。","visualNote":"先看一个最朴素的思路，再一步步升级到真正的 Embedding。"},{"type":"intuition","blocks":[{"k":"为什么不能直接给词编号？","t":"你可能会想：给猫=1、狗=2、苹果=3 不就行了？但问题是：2 和 3 只差 1，可『狗』和『苹果』的语义差得十万八千里。编号把『数字距离』和『语义距离』完全搞乱了。"},{"k":"用一张坐标纸来想","t":"想象一张二维地图，横轴是『是不是动物』，纵轴是『是不是食物』。『猫』放左边偏上，『狗』放它旁边，『苹果』放右上角。位置越近，意思越像。Embedding 本质就是在几百上千维的『坐标纸』上，给每个词找个位置。"},{"k":"一个生活类比","t":"就像地理坐标：北京和天津坐标很近，所以它们在空间上相邻；Embedding 也是给词一个『语义坐标』，语义相近的词坐标也相邻。"}]},{"type":"visual","kind":"embedding-space","title":"Embedding 2D 语义空间","hint":"这是把词『压扁』到二维的示意：意思相近的词会聚在一起。观察猫/狗/狮子聚在『动物角』，苹果/香蕉聚在『食物角』。"},{"type":"how","intro":"Embedding 是怎么『学』出来的？关键思想：一个词的含义 = 它经常和哪些词一起出现。","steps":[{"in":"收集大量文本","process":"从整个互联网 / 语料库里，观察『猫』总是和『狗、宠物、喵、毛』一起出现，而『苹果』总跟『水果、吃、红色』一起出现。","out":"得到每个词在语料里的『共现模式』"},{"in":"用共现模式训练向量","process":"训练算法会分配一组初始数字，然后不断调整，让『一起出现』的词向量越走越近，『从不一起出现』的词向量越走越远。","out":"每个词最终固定成一个向量（如 300 维数字）"},{"in":"用向量距离比较语义","process":"两个词的向量越接近（夹角越小 / 余弦相似度越高），语义越相近。","out":"电脑就能『算』出：猫≈狗，苹果≠猫"},{"in":"送入下游模型","process":"这个数字向量就是神经网络的输入。LLM 只认数字，现在它『看得懂』词了。","out":"模型能对词做运算、比较、生成"}]},{"type":"deep","beginner":["Embedding 是『查表』：模型里有一张巨大的表，每个词一行，那一行数字就是它的向量。训练好之后，直接用查到的数字。","维度越高，能表达的语义越细腻，但计算越贵。常见几百维就够用。"],"advanced":["向量不只是给每个词一个『标签』，它把语义结构编进了几何里：经典例子 king - man + woman ≈ queen，说明方向也承载意义。","Embedding 模型（如 text-embedding 系列）与 LLM 是不同模型：前者把文本压缩成‘定位码’，后者生成文字。它们可以分开训练、分开使用。",{"code":"# 概念示意：余弦相似度，越大越像\nimport numpy as np\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\ncat = np.array([0.9, 0.1])    # 靠近动物方向\napple = np.array([0.1, 0.9])  # 靠近食物方向\nprint(cosine(cat, apple))     # 结果小，说明语义远","lang":"python"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude","note":"内部第一件事就是把你的每个词 Token 转成 Embedding 向量，再送进 Transformer。"},{"name":"搜索引擎语义检索","note":"把『怎么养猫』和『养宠物指南』都向量化，语义相近就能匹配，不必字面相同。"},{"name":"NotebookLM / RAG","note":"把你的资料切成块并向量化，用户提问时在向量空间里『找最像的那几块』再交给模型回答。"}]},{"type":"compare","pairs":[{"a":"Token","b":"Embedding","diff":"Token 是文字切出的‘小块’（词/子词）；Embedding 是把每个小块变成的‘数字向量’。Token 决定切多细，Embedding 决定怎么算语义。"},{"a":"Embedding 模型","b":"LLM","diff":"Embedding 模型把文本压成‘定位向量’（不做对话）；LLM 生成文字。一个是‘编码员’，一个是‘作家’。"},{"a":"给词编号（One-hot）","b":"Embedding","diff":"编号让所有词距离相等、无法表达语义；Embedding 让相近的词距离更近，真正抓住了含义。"}]},{"type":"mistakes","items":["以为 Embedding 只是『给每个词一个数字』。其实是一整串数字（向量），且数字之间有序的相似关系。","以为 Embedding 模型和 LLM 是一个东西。它们是两个分工不同的模型。","以为向量维度越高一定越好。维度高表达力强但更贵、更易过拟合。","以为 Embedding 能理解逻辑。它只捕捉统计上的‘相似’，不保证逻辑正确。"]},{"type":"practice","quiz":[{"q":"为什么不能直接给每个词编个号（猫=1，狗=2）？","opts":["因为编号会让相近的词距离更近","因为编号会破坏语义距离：狗和苹果只差1，但语义差很远","因为编号需要太多内存","因为编号不能用于神经网络"],"a":1,"explain":"编号把‘数字距离’和‘语义距离’搞混了：只有编号差1的两个词会显得很近，但这和它们的含义无关。"},{"q":"两个 Embedding 向量‘夹角越小’，说明什么？","opts":["两个词的语义越相近","两个词的字符串越像","两个词出现频率越接近","两个词长度越接近"],"a":0,"explain":"夹角越小、余弦相似度越高，代表两个词在向量空间里越近，语义越相近。"},{"q":"关于 Embedding 模型与 LLM，正确的是？","opts":["它们是同一个模型","Embedding 模型把文本变向量，LLM 生成文字，二者分工不同","LLM 不做 Embedding","Embedding 模型能写文章"],"a":1,"explain":"Embedding 模型负责‘编码相似度’，LLM 负责‘生成内容’，是不同的模型。"}],"lab":{"title":"Mini Lab：2D 语义空间","desc":"在上方 Embedding 空间里，给新词拖一个位置，观察它和哪群已知词更近。体会‘位置=语义’这件事。","kind":"embedding-space"}},{"type":"connection","known":["AI 世界全景：模型只能处理数字"],"learned":["文字 → 向量，让电脑能算语义","相近的词向量距离更近，用余弦相似度衡量","Embedding 模型与 LLM 分工不同"],"next":"有了‘每个词是一个数字向量’，下一步就是大招：Attention——模型怎么在一句话里决定‘该重点关注哪个词’。再往前一步，你会看到 Transformer 如何把一堆向量变成会翻译、会聊天的大脑。"}]},"l-attention":{"id":"l-attention","title":"Attention｜模型为什么知道该关注哪个词","subtitle":"当模型读到『它』，怎么知道是猫还是狗？为什么句子再长，模型也能把前后的词『对上号』？","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"20 分钟","difficulty":2,"concepts":["attention","qkv","multihead","attention-long"],"prereqLessons":["l-embedding"],"nextLesson":"l-transformer","sections":[{"type":"oneline","text":"Attention 是这样一种机制：模型在理解某个词时，会『回头看一眼』句子里的每一个词，并给它们分别打一个权重分——分数越高的词，模型花越多『注意力』在它身上。于是『它』到底指猫还是狗，模型有了办法分清。"},{"type":"why","before":"上节课我们把每个词变成了向量。但词是孤立的：『猫』『追』『狗』『它』，每一个都只是单独的一个数字串。","problem":"真正的语言是互相指代的。『猫追狗，它跑得飞快』——这个『它』是谁？只看『它』这个词本身，根本答不上来。更糟的是：以前的模型看长句时，越靠前的词就越『记不清』。","need":"我们需要一个机制：在处理任何一个词时，能直接『回看』整句话里的所有词，按『相关程度』加权吸收它们的信息。这就是 Attention——『注意力』。","visualNote":"下面你可以亲手造一句中文，点任何一个词，看它把注意力分给了谁。"},{"type":"visual","kind":"attention-heatmap","title":"Attention 热力图：点一个词，看它关注谁","hint":"输入一句话，点任意一个词（比如那棵/那株），热力图会显示这个词对其它词的『关注权重』——颜色越深，越关注。体型/量词线索会让权重自动偏向正确的词。"},{"type":"intuition","blocks":[{"k":"老师点名：每个词都是老师","t":"把模型想象成在逐一『审问』句子里的每个词。读到『它』这个词时，模型其实在问：『谁能告诉我『它』指谁？』——它会把问题抛向所有词，然后听答案最相关的那几个。"},{"k":"查字典：不是顺序读，而是跳着看","t":"Attention 最反直觉的一点：它不是老老实实从左往右读。读到『它』，它像翻开一本字典快速扫过所有词条，直接锁定『猫』『跑』这些词，记下『我主要靠这几个词来理解自己』。"},{"k":"聚光灯：每个词都有无数盏灯","t":"句子里每个词都举着一盏聚光灯照向其它词。灯越亮，代表『我理解你时越依赖你』。Attention 就是计算这盏灯亮度的过程。"}]},{"type":"how","intro":"Attention 到底怎么『算』注意力？核心就四步：每个词同时扮演三个角色——Query（我找谁）、Key（我是谁）、Value（我的内容）。","steps":[{"in":"乘上三个矩阵，得到 Q / K / V","process":"每个词的向量，分别乘以三个不同的矩阵，变成三个新向量：Query『我要去匹配谁』、Key『我是谁，请拿我来匹配』、Value『我的有效内容』。","out":"单词 → (Query, Key, Value) 三件套"},{"in":"用 Query 和所有 Key 算相似度","process":"以『它』的 Query 为例，和句子里每个词的 Key 做点积（就是 Embedding 课学过的‘方向越像越接近’）。","out":"得到一个分数列表：它 vs 猫 = 高分，它 vs 跑 = 中等……"},{"in":"Softmax 归一化成权重","process":"把所有分数经过 softmax，变成『加起来等于 100%』的权重。这一步保证了分数变成可比的概率。","out":"注意力权重：猫 0.6、跑 0.25、飞快 0.15……"},{"in":"用权重 × Value 加权求和","process":"把每个词的 Value 乘上它对应的权重再全部相加。权重大的词，它的内容在结果里占的份量就大。","out":"『它』经过处理后的新向量 = 主要吸收了『猫』的信息"},{"in":"每个词同时做，得到上下文向量","process":"句子里每个词都执行同样一套操作，得到一批『结合了全局上下文的新向量』。","out":"整个句子从一串孤立向量 → 一串互相理解的向量"},{"in":"多个头并行（多头注意力）","process":"为了不只从一种角度看，模型并行做多组 Q/K/V（不同随机初始化的矩阵），相当于多个不同视角同时观察。","out":"一个头看‘指代关系’，另一个头看‘语法结构’，再一个看‘长度’……"}]},{"type":"deep","beginner":["注意力权重加起来是 1（100%）。Softmax 就是把一坨分数变成「加起来为 1、且大的更大」的数。","不用纠结矩阵怎么算：你只需要记住『Query 找人，Key 被找，Value 是内容，三者相乘加权求和』这句话。","它最厉害的地方：任意两个词无论隔多远都能直接相关——远处那个词和眼前这个词，算注意力的成本完全一样。"],"advanced":["核心公式：Attention(Q, K, V) = softmax(Q·Kᵀ / √d) · V。除以 √d（d 是向量维度）是为了防止点积过大把 softmax 压死（梯度消失）。","Self-Attention：Q/K/V 都来自同一句话，让句子内部互相理解；Cross-Attention：Q 来自一方，K/V 来自另一方（例如翻译时译文找原文的对应）。","复杂度是 O(n²)：n 个词两两都算一遍。这正是上下文窗口成为瓶颈的原因——也是大家研究稀疏注意力、局部注意力的动机。","不要神化注意力可视化：权重高≠模型真『懂』了。它更多是统计相关，不是可解释的因果。",{"code":"# 概念示意：手工算一次注意力（2 个词的极简版）\nimport math\n\ndef softmax(xs):\n    ex = [math.exp(x) for x in xs]\n    s = sum(ex)\n    return [e / s for e in ex]\n\nq = [1.0, 0.0]  # 我是『它』的 Query\nks = {\"猫\": [0.9, 0.1], \"狗\": [0.2, 0.8]}  # 两个词的 Key\n\nscores = {w: round(q[0]*k[0] + q[1]*k[1], 3) for w, k in ks.items()}\nprint(\"点积分数:\", scores)\nweights = dict(zip(scores, softmax(list(scores.values()))))\nprint(\"softmax 权重:\", {w: round(v,3) for w,v in weights.items()})","lang":"python"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude 生成每个词","note":"每生成一个 token，模型都要对上下文做一次 Attention：决定下一个词『更依赖』前面的哪部分。"},{"name":"翻译模型的对齐","note":"把『I love you』翻译成中文时，Attention 会自动让『love』和『爱』『对上号』，哪怕位置完全错开。"},{"name":"代码补全","note":"模型补全函数体时，Attention 帮它『盯住』几千行前的函数签名和参数定义，而不是只看到最近几行。"},{"name":"长文档问答","note":"你在长文章里问『第三部分的结论是？』，Attention 让模型跳过大段无关内容，直接聚焦第三部分的句子。"}]},{"type":"compare","pairs":[{"a":"RNN 顺序处理","b":"Attention 全局直连","diff":"RNN 必须一个字一个字按顺序传，远处信息会衰减；Attention 任意两个位置直接相联，没有距离衰减。"},{"a":"Self-Attention","b":"Cross-Attention","diff":"Self 是同句话内部互相理解；Cross 是让一方去『读』另一方（翻译、RAG 上下文注入都用它）。"},{"a":"单头注意力","b":"多头注意力","diff":"单头只有一种‘看法’；多头并行多组 Q/K/V，相当于同时用多个角度理解，效果明显更好。"}]},{"type":"mistakes","items":["以为 Attention 是『看一遍就记住』的长期记忆。它不是记忆，而是每次计算时动态分配的关注权重——注意力要重新算，不会存下来。","以为注意力可视化等于模型的可解释性。权重高代表统计上相关，不代表模型逻辑上『是因为这个』。","把『注意力』和『上下文窗口』混为一谈。窗口决定能看多远，Attention 决定窗口内怎么分配关注。","以为只看『最近几个词』。Attention 恰恰是全局的——它牺牲计算量换来的是真正看全上下文。"]},{"type":"practice","quiz":[{"q":"Attention 中，Query、Key、Value 各自的作用最准确的说法是？","opts":["Q 是内容，K 是找人，V 是被找","Q 在找人，K 是被找的标签，V 是被吸收的内容","三者完全相同","Q 是权重，K 是分数，V 是标签"],"a":1,"explain":"Q（Query）发起匹配→去找谁；K（Key）告诉别人『我是谁』、供匹配；V（Value）是被吸收进结果的真正内容。"},{"q":"为什么说 Attention 解决了 RNN『记不住长句』的问题？","opts":["因为它是顺序处理的","因为任意两个词都可以直接相关，不随距离衰减","因为它把句子变短了","因为它只关心最近的词"],"a":1,"explain":"RNN 依赖顺序传递，距离远信息衰减；Attention 让任意两个位置直接相连，远近一视同仁。"},{"q":"把注意力分数做 softmax 是为了？","opts":["让负数变成正数","让分数变成加和为 1 的权重，且强调大的","让计算更快","让向量变短"],"a":1,"explain":"Softmax 把一坨任意分数变成『加起来为 1』、且大者更大的概率分布，这样加权求和才合理。"}],"lab":{"title":"Mini Lab：亲手算一次 Attention","desc":"在上方热力区输入你的一句话，点不同词观察权重分配；再试试把量词改掉，体会权重如何跟着语义线索移动。","kind":"attention-heatmap"}},{"type":"connection","known":["词 → 向量（Embedding）","向量方向越像、语义越近（余弦相似度）"],"learned":["每个词同时是 Query / Key / Value","注意力 = 相似度分数 → softmax 权重 → 加权求和","Self-Attention 让句子内部互相理解，多头提供多视角"],"next":"Attention 是 Transformer 的心脏。下一课我们会看到：怎么把这一套注意力，组装成一个能真正训练、能翻译能写诗的完整大模型架构——Transformer。再往后，你会明白 RAG 和 Agent 都是在这个架构上叠出来的能力。"}]},"l-transformer":{"id":"l-transformer","title":"Transformer｜大模型的地基架构","subtitle":"为什么 2017 年诞生的它，能横扫翻译、写作、代码、对话？一个 20 分钟看懂『大模型的心脏是怎么拼出来的』。","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"25 分钟","difficulty":3,"concepts":["transformer","position-enc","multihead","attention"],"prereqLessons":["l-attention"],"nextLesson":"l-rag","sections":[{"type":"oneline","text":"Transformer 是 2017 年提出的一个『把注意力机制组装成完整大脑』的架构：它用『多头注意力 + 前馈网络 + 残差连接 + 位置编码』堆成一叠一层又一层的模块，能并行、能训练得非常深，从此成为 ChatGPT、Claude、Gemini 的共同地基。"},{"type":"why","before":"上一课我们有了 Attention：任何两个词都能直接互相关注。但这只是一块『积木』，离一个能真正工作的模型还差很远。","problem":"只靠 Attention 还不够：1) 它不知道词的位置——『猫追狗』和『狗追猫』词全一样；2) 一层注意力学到的东西有限；3) 堆深了又容易训练不动。","need":"Transformer 就是给 Attention 配上『位置感、深度、稳定训练的装备』，把一块积木组装成一台可训练的机器。","visualNote":"下面这张图是 Transformer 的主干流水线，你可以一步一步点开看每一层在干什么。"},{"type":"visual","kind":"transformer-flow","title":"Transformer 主干流水线：一步一步看","hint":"点击【下一步】，观察一个词从『数字向量』走到『预测下一个词』的完整过程：输入 → 位置编码 → 多头注意力 → 残差+归一化 → 前馈网络 → 重复堆叠 → 输出。"},{"type":"intuition","blocks":[{"k":"一个加工厂流水线","t":"把 Transformer 想成一家加工厂：原料是一串向量。每个工位（层）做两件事——同事协作（注意力，大家互通信息）＋ 个人精加工（前馈网络，每个词独自想更深）。一层做完送下一层，共 N 层。"},{"k":"用乐高积木来想","t":"Attention 只是其中一块积木。Transformer 是说明书：告诉你『这一层要怎么拼：注意力 + 残差 + 归一化 + 前馈；然后复制粘贴 N 次』。"},{"k":"办公室里的并行会议","t":"RNN 像只有一个话筒的圆桌，每人必须轮流说（慢）；Transformer 像微信群——所有人同时发言、同时收听（并行快），谁跟谁相关自己匹配（注意力）。"}]},{"type":"how","intro":"一个词在 Transformer 里的完整旅程。每一步都围绕同一批向量做变换，最后模型学会『预测下一个词』。","steps":[{"in":"输入：词向量 + 位置编码","process":"每个词先查表得到 Embedding 向量。但向量本身不含『位置』，所以再加一个位置信息（位置编码），让模型知道『这是第 5 个词』。","out":"每个词带上位置的向量"},{"in":"多头注意力层（同事协作）","process":"这一层让每个词结合全局上下文：用上节课的 Q/K/V 机制，多组并行，每组的输出再拼接。词的『含义』从此包含了周围所有词。","out":"每个词变成『理解上下文后的新向量』"},{"in":"残差连接 + 归一化（稳定训练）","process":"把『进来的向量 + 注意力算完的向量』加在一起（残差），再做归一化。这就像修了一条高速公路：信息不衰减地直接流过深层。","out":"浅层信息可以无损‘抄近道’到达深层，网络能堆得深"},{"in":"前馈网络 FFN（个人精加工）","process":"一个两层全连接网络，对每个词独立再做非线性变换，让模型有能力表达更复杂的关系。","out":"每个词被‘再想一想’，表达能力增强"},{"in":"重复堆叠 N 层","process":"把『注意力 + 残差 + 归一化 + 前馈』这组动作复制 N 次叠起来（GPT 有十到上百层）。每层都让词的表示更抽象、更接近任务。","out":"深层的向量已经‘浓缩’了整句话的语义"},{"in":"输出：预测下一个词","process":"最后一层接一个线性层 + softmax，把向量变成『词典里每个词的概率』，模型取概率最高的作为下一个词。","out":"生成一个词 → 拼回输入 → 继续预测下一个词"}]},{"type":"deep","beginner":["位置编码就是给每个词加个『第几个』的记号，否则『猫追狗↔狗追猫』对模型来说字全一样。","残差连接简单说就是『进来和出去加一起』，像搭桥——让深层的梯度不会消失，模型才能堆数十上百层。","前馈网络 FFN 是给每个词单独『换个角度想一遍』，和注意力（词与词协作）分工不同、缺一不可。","GPT 其实只用了 Transformer 的一半：只有『解码器』那套（Decoder-only），用来不停地预测下一个词。"],"advanced":["核心是 Decoder：每个 token 只看自己和前面（因果掩码 causal mask），保证预测时不‘偷看’未来。这是它和编码器最大区别。","缩放点积注意力公式：Attention = softmax(QKᵀ/√d)V。除以 √d 防点积过大导致梯度消失/softmax 饱和。","三种架构：Encoder-only（BERT：理解）、Decoder-only（GPT：生成）、Encoder-Decoder（T5：翻译/转换）。ChatGPT 系清一色 Decoder-only。","残差连接 + LayerNorm（Pre-LN 顺序）是训练稳定性的关键工程细节，是让它能堆到千亿参数的原因之一。","复杂度 O(n²)：上下文窗口越大成本越高——这直接决定了『长上下文为什么贵』『为什么要 RAG』。",{"code":"# 概念示意：位置编码的经典公式（不必实现，体会它想表达什么）\nimport math\n\ndef pos_encoding(pos, d_model=8):\n    # 给第 pos 个词生成 d_model 维的位置向量，奇偶通道分别用 sin/cos\n    vec = []\n    for i in range(d_model):\n        angle = pos / (10000 ** (2 * (i // 2) / d_model))\n        vec.append(round(math.sin(angle), 3) if i % 2 == 0 else round(math.cos(angle), 3))\n    return vec\n\nfor p in [0, 1, 2, 3]:\n    print(f\"第{p}个词的位置: {pos_encoding(p)}\")","lang":"python"}]},{"type":"realworld","items":[{"name":"ChatGPT / GPT 系列","note":"Decoder-only Transformer：单纯地、一层层地预测下一个词，就长出了对话和推理能力。"},{"name":"Claude / Gemini","note":"同一架构的不同工程实现：同样的多头注意力 + 深层堆叠，在尺度与训练技巧上各有差异。"},{"name":"翻译与摘要模型（T5/BART）","note":"Encoder-Decoder 结构：编码器读懂全文，解码器再一句句生成译文或摘要。"},{"name":"代码补全（Codex 前身 CodeGPT）","note":"把代码当‘另一种语言’喂给 Decoder-only Transformer，学会了补全、续写、改 bug。"}]},{"type":"compare","pairs":[{"a":"RNN","b":"Transformer","diff":"RNN 顺序串行、远处信息衰减、难并行；Transformer 全局直连、天然并行、能堆深。2017 后几乎完全取代 RNN。"},{"a":"Encoder-only（BERT）","b":"Decoder-only（GPT）","diff":"前者双向读全文、擅长‘理解’（分类/检索）；后者只能从左往右、擅长‘生成’（对话/写作/代码）。"},{"a":"单层注意力","b":"N 层堆叠的 Transformer","diff":"单层只做一次‘互相看’；Transformer 把多次‘互相看+精加工’叠起来，让表示一层比一层抽象。"}]},{"type":"mistakes","items":["以为『Transformer = Attention』。Attention 只是其中的一个子模块，完整架构还包括残差、归一化、前馈、位置编码。","以为 BERT 和 GPT 一样。BERT 双向理解、GPT 单向生成，职权完全不同。","以为层数越多一定越好。层越深效果提升有边际，还会带来更大的算力和训练难度。","把『位置编码』当可选项。没有它，『猫追狗』和『狗追猫』对模型来说完全一样——这可是天壤之别。"]},{"type":"practice","quiz":[{"q":"为什么 Transformer 需要位置编码？","opts":["为了让向量维度变大","因为注意力本身不含位置信息，没有位置编码『狗追猫』和『猫追狗』无法区分","为了加快计算","为了让训练更快收敛"],"a":1,"explain":"注意力是把所有词互相加权，天然『不记得顺序』；位置编码把‘第几个’注入向量，模型才知道顺序。"},{"q":"残差连接（Residual）的主要作用是？","opts":["增加参数数量","让信息能无损跨层传递，网络可以堆得很深且训练稳定","让模型更快生成","代替位置编码"],"a":1,"explain":"把输入和输出相加，像搭桥一样让信息直达深层，缓解深层网络的梯度消失，是能堆几十上百层的关键。"},{"q":"GPT 属于哪种结构？","opts":["Encoder-only","Decoder-only","Encoder-Decoder","既不是编码器也不是解码器"],"a":1,"explain":"GPT 只用解码器（带因果掩码、从左往右生成），反复预测下一个词。"}],"lab":{"title":"Mini Lab：走一遍 Transformer 流水线","desc":"在上方流水线里逐步播放，观察同一个词每经过一层，它的『表示』如何从字面向量变成富含上下文的向量，最后被用来预测下一个词。","kind":"transformer-flow"}},{"type":"connection","known":["Attention：Q/K/V 加权求和，让词与词互相关注","词是向量，语义可算相似度"],"learned":["Transformer = 多头注意力 + 残差 + 归一化 + 前馈网络的 N 层堆叠","位置编码让模型感知顺序","GPT 是 Decoder-only，靠预测下一个词长出能力"],"next":"Transformer 有了，模型『什么都会但只记得训练时的知识』。下一课我们解决这个关键问题：RAG —— 怎么让模型在回答前先去『你的资料库』查资料，从而回答它没学过的私有内容。"}]},"l-rag":{"id":"l-rag","title":"RAG｜让模型『查资料』再回答","subtitle":"为什么 ChatGPT 不知道你的私有文档？怎么让模型『翻开你的资料』再回答？从切块到生成，一条流水线看懂 RAG。","category":"c07-rag","chapterTitle":"第一章 · RAG 全流程","level":"base","estTime":"25 分钟","difficulty":2,"concepts":["rag-pain","rag-pipeline","chunking","emb-vector-store","vector-search","rerank"],"prereqLessons":["l-transformer","l-embedding"],"nextLesson":"l-agent","sections":[{"type":"oneline","text":"RAG（检索增强生成）就是：让模型在回答之前，先去你的资料库里『检索』相关的内容，把查到的片段拼进上下文，再让模型『照着资料』作答。于是它能回答自己『没学过』的私有知识，还能顺便指出出处。"},{"type":"why","before":"经过前面几课，我们已经有了一个很聪明的模型（Decoder-only Transformer）。但它有一个致命限制：它只知道『训练时见过的东西』，而且经常一本正经地编造（幻觉）。","problem":"1) 你的合同、内部 SOP、论文——模型训练时根本没见过；2) 即使见过，版本也过期了；3) 让它硬答私有问题，它大概率会编。重新训练整个模型又贵又慢。","need":"与其改模型的『脑子』，不如每次回答时给它配一本『说明书』：先把相关的资料找出来喂给它。这个思路就是 RAG，简单、便宜、可随时更新。","visualNote":"下面这条流水线是 RAG 的完整精神：切块 → 向量化 → 检索 → 重排 → 组装 → 生成。你可以一步步看。"},{"type":"visual","kind":"rag-pipeline","title":"RAG 完整流水线：从文档到回答","hint":"逐步播放：上传文档 → 切块 Chunk → 向量化 Embedding → 存入向量库 → 用户提问 → 检索 Top-K → 重排 Rerank → 组装上下文 → 生成回答（带引用）。每一步都点开看细节。"},{"type":"intuition","blocks":[{"k":"开卷考试 vs 闭卷考试","t":"普通 LLM 是闭卷考试：只凭脑子里的记忆答题，记不住就编。RAG 是开卷考试：允许先翻资料，翻到相关的那页再答。显然开卷更可靠。"},{"k":"图书馆查书再回答","t":"你问『公司年假制度是什么』。RAG 不会直接在记忆里编，而是先去公司知识库『检索』年假相关文档，找到后引用着回答。"},{"k":"不是变聪明，是带了参考书","t":"RAG 不提升模型智商，而是每次回答都『带着最新的、属于你的资料』。资料更新，回答立刻跟着更新，不用重新训练。"}]},{"type":"how","intro":"RAG 分两个阶段：『入库』（离线，把文档变成可检索的向量库）和『查询』（在线，用户提问时检索+生成）。下面是完整流程。","steps":[{"in":"为什么需要 RAG（先想清楚）","process":"场景：需要回答私有/最新/超长知识，或需要答案可溯源。如果模型自带答案且内容不敏感，RAG 可能不是最优选。","out":"想清楚：RAG 解决的是『知识更新与私有化』，不是『模型变聪明』"},{"in":"切块 Chunking","process":"把长文档（PDF/网页）切成几百上千字的小块。切多大、是否重叠、按什么切（标题/段落）会直接影响检索质量。","out":"文档 → 若干 chunk（带元数据：来源、页码）"},{"in":"向量化 Embedding","process":"用 Embedding 模型把每个 chunk 变成一个向量（上上节课学的：文字 → 数字，语义相近的向量相近）。","out":"每个 chunk → 一个向量"},{"in":"存入向量库 VectorDB","process":"把『向量 + 原文 + 元数据』一起存进向量数据库（如 FAISS、Milvus、pgvector），并建好索引以便快速搜索。","out":"可毫秒级完成相似检索的向量库"},{"in":"检索 Retrieval","process":"用户提问时，把问题也向量化，然后在向量库里找『最像的 Top-K 块』（一般是余弦相似度排名）。","out":"问题 → 找出最相关的 N 个 chunk"},{"in":"重排序 Rerank","process":"初筛的 Top-K 可能不够准。用一个更精细的模型把这 K 个再排一次，把真正相关的提到最前、过滤掉噪音。","out":"更精准的候选（通常是前 3~5 块）"},{"in":"组装上下文","process":"把检索到的 chunks 拼进 Prompt，附上用户问题，并提示模型『只依据下面的资料回答，引用出处』。","out":"一份带参考资料的完整 Prompt"},{"in":"生成 Generation","process":"LLM 基于这份『资料 + 问题』生成回答，并标注引用了哪一段。","out":"有出处、可更新、针对私有知识的回答"}]},{"type":"deep","beginner":["chunk 太小：语义不完整；chunk 太大：噪音多、还可能被截断。常见几百~一千字 + 20% 重叠。","向量相似≠字面相似：改个说法（『年假』 vs 『带薪假期』）有时也能检索到，这是向量检索比关键词厉害的地方。","RAG 不会凭空创新知识，它只会『引用你给的东西』——所以资料库质量≈回答质量。"],"advanced":["混合检索（Hybrid）：向量检索（语义）+ 关键词检索（BM25，精确匹配人名/编号）结合起来，互补漏检。","Rerank 为什么必要：初检向量健壮但不够精，专门的 rerank 模型（cross-encoder）能逐对精判相关性，显著提升准确率。","引用溯源（Citation / Grounding）：让模型输出时带上片段编号，用户能核对来源，也是落地合规的关键。","GraphRAG 等进阶：把实体关系建成图结构检索，适合『要跨多个文档推理』的难题。","评估：召回率（该找到的找到没）与准确率（找到的是不是都相关），以及最终回答的有据率。",{"code":"# 概念示意：RAG 里最核心的一步——向量检索（伪代码思路）\nimport numpy as np\n\n# 假设我们已经把文档块向量化并存在 chunks 里\nchunks = [\"年假制度：入职满一年享 5 天…\", \"报销流程：金额低于 1000 走 OA…\"]\nchunk_vecs = [np.array([0.9, 0.1]), np.array([0.1, 0.9])]  # 示意向量\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\nquery_vec = np.array([0.85, 0.15])  # 用户问题『年假有几天』向量化\nscores = sorted(((cosine(query_vec, v), i) for i, v in enumerate(chunk_vecs)), reverse=True)\ntop1 = chunks[scores[0][1]]\nprint('最相关的资料块:', top1)  # → 年假制度那一段","lang":"python"}]},{"type":"realworld","items":[{"name":"NotebookLM","note":"你上传 PDF/视频，它检索你的资料再回答，还能生成带引用的播客、摘要。教科书级 RAG 产品。"},{"name":"企业内部知识库客服","note":"把 SOP、产品手册向量化，客服 AI『查文档再回答』，而不是对着空气编。"},{"name":"Claude Projects / 附件上传","note":"给对话挂上资料，模型按需检索引用，本质是一套轻量 RAG。"},{"name":"搜索增强的 ChatGPT / Perplexity","note":"它先联网检索实时网页，再基于检索结果回答——也是 RAG（用 web 当『向量库』）。"}]},{"type":"compare","pairs":[{"a":"RAG","b":"微调 Fine-tuning","diff":"RAG 每次查最新资料、可溯源、便宜、可随时更新；微调是改模型‘脑子’、更像学风格学格式。知识类更新首选 RAG。"},{"a":"向量检索","b":"关键词检索","diff":"向量找‘语义相近’（换个说法也能找到）；关键词精准匹配字面（找人名编号更稳）。生产常用混合。"},{"a":"RAG","b":"超长上下文","diff":"RAG 主动挑最相关片段、便宜快速；超长上下文把整本书塞进去、贵且容易‘淹没’重点。大库优先 RAG。"}]},{"type":"mistakes","items":["以为 RAG = 把文档一股脑塞进提示词。真正的 RAG 要先切块、向量化、检索、重排，只喂最相关的几块。","忽略 chunking 质量。切坏了，再好的模型也答不准——检索进来自的都是垃圾。","以为检索到就完了，不做 rerank。初检的 Top-K 常有噪音，重排能明显提高准确率。","忘记引用溯源。落地到严肃场景（医疗/法务/企业），没有出处等于不可信。","把 RAG 当成解决幻觉的万灵药。资料里没有或检索失败时，模型照样可能编。"]},{"type":"practice","quiz":[{"q":"RAG 解决的核心问题是？","opts":["让模型数学更好","让模型能回答私有/最新知识并可溯源，而不用重新训练","让模型更快生成","让模型学会编程"],"a":1,"explain":"RAG 的核心价值：用检索到的外部资料补充模型没学过的知识，便宜、可更新、可引用。"},{"q":"RAG 的『入库』阶段，正确的顺序是？","opts":["向量化 → 切块 → 存库","切块 → 向量化 → 存库","存库 → 向量化 → 切块","检索 → 切块 → 向量化"],"a":1,"explain":"先把长文档切成 chunk，再逐块向量化，最后连向量带原文存进向量库。『检索』是查询阶段的事。"},{"q":"为什么生产系统里还要做 Rerank 重排？","opts":["为了多花一点算力","初检的 Top-K 常有噪音，用更精细的模型重排能显著提升相关性与准确率","为了把回答变长","为了跳过 embedding"],"a":1,"explain":"向量初检健壮但不精，专门的 rerank 模型能逐对精判，把真正的相关片段提到最前。"}],"lab":{"title":"Mini Lab：走一遍 RAG 全流程","desc":"在上方流水线逐步播放：看一份文档如何被切块、向量化、检索、重排，最终变成一次带引用的回答。理解每一步在哪犯了错会怎样。","kind":"rag-pipeline"}},{"type":"connection","known":["Embedding：文字 → 向量，语义相近的向量相近","Transformer：模型的‘脑子’","上下文窗口：模型一次能看多少"],"learned":["RAG 让模型先检索资料再回答，解决私有/最新/可溯源","完整流程：切块 → 向量化 → 向量库 → 检索 → 重排 → 生成","RAG vs 微调 vs 长上下文 的取舍"],"next":"RAG 让模型『会查资料』，但模型还是停在『你说一句、它应一句』。下一课是这个旅程的终点也是新起点：Agent —— 让模型自己拆目标、自己动手调用工具，把一整件事做完。"}]},"l-agent":{"id":"l-agent","title":"Agent｜让 AI 自己动手做事","subtitle":"为什么 ChatGPT 只能在对话框里打字，而 Codex 能改你的代码、跑你的测试、提交 PR？Agent 就是把『会说话』的模型，变成『会做事』的执行者。","category":"c08-agent","chapterTitle":"第一章 · 从会说到会做","level":"base","estTime":"25 分钟","difficulty":2,"concepts":["agent-intro","agent-loop","tool-use","agent-planning","agent-memory","agent-reflection"],"prereqLessons":["l-rag","l-transformer"],"nextLesson":"l22-ai-coding","sections":[{"type":"oneline","text":"Agent（智能体）不是换个厉害的模型，而是给模型装上一个『决策循环』：它会自己拆目标、自己调用工具（读写文件、执行代码、搜网页）、观察结果、再决定下一步，如此循环直到把事情做完。同样一个模型，套上这个循环，就从『只会回答』变成了『会做事』。"},{"type":"why","before":"到这一课，我们有了很聪明的模型、也有了让它『查资料』的 RAG。但你还是有个困扰：让 ChatGPT 整理个表格它倒是能，让它『去我仓库里改掉那个 bug』，它做不到。","problem":"因为聊天模型只有一张『嘴』：它只能输出文字，看不见你的文件、读不了你的代码、跑不了测试命令。你让它『操作仓库』，它连仓库在哪都不知道。","need":"Model（思考）+ Tools（手和眼）+ Loop（循环驱动）= Agent。它想一下 → 动一下 → 看一眼结果 → 再想 → 再动。这就是 ChatGPT 和 Codex 的分水岭。","visualNote":"下面这个循环图就是 Agent 的灵魂——你可以点每一步看它到底在干什么。"},{"type":"visual","kind":"agent-loop","title":"Agent 循环：想 → 做 → 看 → 再想","hint":"逐步播放一个 Agent 修复 bug 的完整循环：理解目标 → 拆计划 → 调用工具（读代码/改代码/跑测试）→ 观察结果 → 陷入失败 → 修正 → 完成并交付。"},{"type":"intuition","blocks":[{"k":"计算器只会算，助理会办事","t":"普通聊天模型像一台高级计算器：你问它答。Agent 像你的助理：你交代一件事，它自己拆步骤、打电话（调工具）、核对结果，办完给你汇报。"},{"k":"不是变聪明，是变『能动』","t":"它没有比 ChatGPT 更聪明——它只是多了一圈『能动手、能看反馈、能再试』的回路。代码还是那个代码，差别在于它学会了『执行-反馈-调整』。"},{"k":"交给你手里没钥匙的实习生 vs 有钥匙的实习生","t":"ChatGPT 是没钥匙的实习生：看到门（需要改文件）只会描述『你应该去改那个文件』。Agent 是有钥匙的实习生：自己开门、改文件、跑测试、看结果、再改。"}]},{"type":"how","intro":"一个 Agent 改 bug 的完整工作过程。核心就一句话：目标 → 循环（想 + 做 + 看）→ 交付。","steps":[{"in":"理解目标","process":"用户下达：『修好注册页面的 bug』。模型先把模糊目标翻译成具体子任务列表。","out":"一个可执行的任务清单"},{"in":"规划 Planning","process":"它推理出步骤：先找到注册页代码 → 读源码定位问题 → 想怎么改 → 改 → 跑测试验证。","out":"Agenda：找代码 / 读 / 改 / 测"},{"in":"调用工具 Tool Use（Act）","process":"它请求调用工具：read_file 读代码、edit_file 修改、run_command 跑测试。工具返回结果。","out":"一次具体的‘动手’"},{"in":"观察结果 Observe","process":"看到工具返回值：测试报错，或编译失败。它读到反馈，判断是否达到目标。","out":"对‘刚才做的事情对不对’的感知"},{"in":"循环 Loop：再想再做","process":"若未达成，回到‘想’：根据报错调整方案，再调用工具。如此循环直到测试通过或放弃。","out":"反复的 agent loop（这正是和 ChatGPT 的本质区别）"},{"in":"交付与汇报","process":"任务完成：向用户总结改了什么、测试结果，甚至主动提交 PR、申请权限。","out":"一件完成的事，而不是一段话"}]},{"type":"deep","beginner":["Agent Loop 不是魔法：本质就是模型的 for/while 循环——决定下一步 → 调用工具 → 看结果 → 决定再下一步。","工具（Tool）就是『一个函数』：read_file、write_file、run_command、web_search。模型学会了在合适时机调用它们。","最朴素的 Agent = LLM + 工具集 + 一个决定何时停止的循环。它也可以有记忆和规划，但核心就是这个循环。"],"advanced":["Tool Use / Function Calling：模型输出结构化的『要调用哪个函数、传什么参数』，由系统执行并把结果喂回去，形成闭环。","记忆分两层：短期（当前任务的对话/工具历史）与长期（跨对话的项目知识、偏好，常存向量库）。","Planning 范式：ReAct（Reason + Act 交替）、Plan-and-Execute（先定计划再逐步执行、plan 可被动态修订）。","权限与安全 Permission：Agent 不会无限乱来——危险操作（删文件、花钱、外发数据）要求用户授权（approval gate）。","MCP（Model Context Protocol）：统一『工具/数据源』接入协议，让一个 Agent 能标准化接入文件系统、数据库、浏览器等多种工具，避免每家写一套私有接口。","Reflection 反思：让 Agent 回顾刚才失败的原因再调整，显著提升长任务的可靠性。多 Agent 协作则是多个专业 Agent 分工。",{"code":"# 概念示意：Agent 循环的骨架，就长这样\nwhile not goal_reached:\n    thought = model.think(state, memory)      # 想：我要做哪一步？\n    if thought.should_stop: break              # 判断是否完成\n    tool_result = call_tool(thought.tool_call) # 做：调用工具\n    state.append(tool_result)                  # 看：把结果存进上下文\n    memory.update(state)                       # 记住教训\n# 交付\nreport(model.summarize(state))","lang":"python"}]},{"type":"realworld","items":[{"name":"Codex / Claude Code","note":"Agentic Coding 的典型：能读你的仓库、找 bug、改代码、跑测试、提交 PR。这就是『ChatGPT 做不到、它做得到』的原因——它装了代码工具 + agent loop。"},{"name":"Cursor / Windsurf","note":"IDE 里的 Agent：理解整个项目上下文，跨多个文件完成重构，而不只是一行行补全。"},{"name":"浏览器 Agent（如 Browser Use / Operator）","note":"自己打开网页、读取、点击、填表，把『逛网页办事』自动化。"},{"name":"n8n / 工作流编排","note":"让 Agent 串联多个工具/API 完成端到端业务流程（取数→处理→发通知）。"}]},{"type":"compare","pairs":[{"a":"Chatbot（聊天机器人）","b":"Agent（智能体）","diff":"Chatbot 只输出文字、终结于回答；Agent 拆目标、调工具、看结果、循环迭代，终结于『做成事』。"},{"a":"单次工具调用","b":"多步 Agent Loop","diff":"可以调一个工具的助手只是初级；真正的 Agent 会根据结果决定下一调用，持续多轮直到完成。"},{"a":"RPA（脚本化机器人）","b":"LLM Agent","diff":"RPA 按写死的剧本执行、一变就崩；Agent 动态推理、能处理没见过的异常情况。"}]},{"type":"mistakes","items":["以为 Agent 只是『换了个更聪明的模型』。本质差别在『循环 + 工具』，不是模型本身。","以为 Agent 能无限可靠地自主执行。它也会反复失败、会犯错，所以需要权限门槛（approval gate）、观测和护栏。","忽视权限与安全。放任 Agent 删文件/发数据/花钱是最危险的坑，生产环境必须加授权与审计。","把『会调用工具』当成『有规划和反思』。会调一个函数 ≠ 会拆解复杂目标并自我修正，后者才是 Agent 的进阶。","以为多 Agent 一定更好。多数场景单 Agent 更简单可控，盲目堆 Agent 只会带来编排复杂度和成本。"]},{"type":"practice","quiz":[{"q":"为什么 ChatGPT 不能操作你的仓库，而 Codex 可以？","opts":["因为 Codex 模型更聪明","因为 Codex 被接上了工具（读写文件/跑命令）+ Agent 循环，ChatGPT 只有对话输出","因为 ChatGPT 没联网","因为模型大小不同"],"a":1,"explain":"决定性差异不是模型智能，而是 Agent 结构：工具让它可以『动手』，循环让它能『做→看→修正』直到完成。"},{"q":"Agent Loop 的核心循环顺序是？","opts":["看 → 做 → 想","想 → 做 → 看 → 再想","只做不看不回头","想 → 想 → 想"],"a":1,"explain":"标准 agent loop：决定下一步（想）→ 调用工具（做）→ 观察结果（看）→ 根据结果再决定下一步（再想），循环到目标达成。"},{"q":"MCP（Model Context Protocol）主要解决什么问题？","opts":["让模型跑得更快","统一 Agent 接入工具/数据源的接口标准，避免各家用私有协议","代替向量数据库","让模型更聪明"],"a":1,"explain":"MCP 是 Agent 与文件、数据库、浏览器等外部工具的标准化接入协议，一次接入、到处复用。"}],"lab":{"title":"Mini Lab：跑一次 Agent 循环","desc":"在上方循环图里，设一个任务（修 bug / 发邮件 / 整理数据），观察 Agent 每轮『想什么、调哪个工具、看到什么结果』，直到完成或需要你授权。","kind":"agent-loop"}},{"type":"connection","known":["Transformer：模型怎么生成内容","RAG：怎么让模型查资料","工具调用 Function Calling"],"learned":["Agent = 模型 + 工具 + 循环（想→做→看→再想）","它能拆目标、规划、调用工具、观察反馈、反复修正","关键工程点：Tool Use / Memory / Planning / Permission / MCP"],"next":"到这里，你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。想继续深入，建议顺着你的目标分支走：做产品学 LLM 应用与 RAG，写代码就进入 AI 编程（Agentic Coding / Claude Code）那一章。"}]}},"lessonsByCat":{"c01-ai-world":[{"id":"l00-ai-world","title":"一张图看懂整个 AI 世界","subtitle":"在学任何一个概念之前，先拿到整张地图：你现在站的哪里，接下来要走到哪里。","category":"c01-ai-world","chapterTitle":"第一章 · AI 全景","level":"base","estTime":"10-15 分钟","difficulty":1,"concepts":["ai-what","ai-ml-dl","ai-apps","ai-limits"],"prereqLessons":[],"nextLesson":"l01-ai-vs-ml-dl","sections":[{"type":"oneline","text":"AI（人工智能）是一整片森林；机器学习是其中会『自己从数据里找规律』的那片树；深度学习是最能长的那几棵；大语言模型（LLM）是最近最抢眼、能和你聊天的那一棵。"},{"type":"why","before":"在你被一大堆名词淹没之前，先停下来。Token、Attention、RAG、Agent……如果不知道它们各自站在地图的哪个位置，学一个忘一个。","problem":"很多初学者的问题不是『不够努力』，而是没有地图：他不知道现在学的东西，将来会连到哪里。","need":"所以第一节课我们不讲细节，只画一张总地图，让你知道：整个 AI 世界的骨架是什么，你将来要学的每一块长在哪里。","visualNote":"下面这张图就是你要带走的『世界地图』。"},{"type":"visual","kind":"ai-world-map","title":"AI 世界全景图","hint":"从最外层的 AI 一路往内收缩到 LLM；再往外展开 Vision / Speech / Agent / RAG 等应用方向。点击你能看懂就往下一层。"},{"type":"intuition","blocks":[{"k":"用一棵树来想","t":"把 AI 想成一棵树：树干是『机器学习』——所有『机器自己学』的方法都从这儿长出来；从树干分出的粗枝是『深度学习』；深度学习上最茂密的一枝长出了『大语言模型』。你平时用的 ChatGPT 只是这棵树上的一颗果实。"},{"k":"用俄罗斯套娃来想","t":"AI 是最大的套娃，Machine Learning 是里面一层，Deep Learning 再里面一层，LLM 是最小最精致的那层。每往里一层，都建立在外层之上。"},{"k":"一句话总结链条","t":"AI ⊃ Machine Learning ⊃ Deep Learning ⊃ Foundation Model ⊃ LLM。这一个箭头链条，就是整张地图的主干。"}]},{"type":"how","intro":"把整张地图拆成一个从内到外、再到应用的主干流程，你学完至少知道每块知识的归属。","steps":[{"in":"AI（人工智能）","process":"最上层总称：让机器表现出智能的一切技术。","out":"范围最大，包含规则、搜索、机器学习等"},{"in":"Machine Learning","process":"机器从数据里自动找规律，而不是人写死规则。","out":"监督 / 无监督 / 强化学习 三大流派"},{"in":"Deep Learning","process":"用『多层神经网络』来学习，能力更强的机器学习子集。","out":"CNN、RNN、Transformer 等网络结构"},{"in":"Foundation Model（基础模型）","process":"在大规模数据上预训练好的通用模型，可以微调复用到很多任务。","out":"LLM（语言）、视觉模型、多模态模型"},{"in":"LLM（大语言模型）","process":"以『预测下一个词』为核心任务训练出来的大模型，学会了语言与世界知识。","out":"ChatGPT、Claude、Gemini 的前身"},{"in":"围绕 LLM 的应用层","process":"为了让模型更好用，叠加外围技术。","out":"Prompt 提示、RAG 检索、Agent 智能体、多模态"}]},{"type":"realworld","items":[{"name":"ChatGPT","note":"纯 LLM 的产品：你打字，它生成下一个词。"},{"name":"Claude / Gemini","note":"同样是 LLM，但被训练得在不同任务上更擅长。"},{"name":"NotebookLM","note":"用 RAG：你上传资料，它『查你给的材料』再回答。"},{"name":"Codex / Claude Code","note":"用 Agent：不只是回答，还会调用工具去改代码、跑命令。"}]},{"type":"compare","pairs":[{"a":"AI","b":"Machine Learning","diff":"AI 是目标（机器有智能）；机器学习是其中一种『用数据学出来』的手段。早期 AI 靠人写规则，也属于 AI。"},{"a":"Machine Learning","b":"Deep Learning","diff":"都是『从数据学习』；深度学习特指用多层神经网络，能自动从数据中提取特征，能力更强。"},{"a":"LLM","b":"Foundation Model","diff":"LLM 是专门做语言的基础模型；Foundation Model 是更大的类：还包括视觉、多模态等。"}]},{"type":"mistakes","items":["把『AI』『机器学习』『深度学习』当同义词——其实是一层层包含关系。","以为 ChatGPT = 整个 AI。它只是 LLM 的一颗果实，AI 世界还有视觉、语音、Agent、机器人等一大堆。","以为学 AI 必须先把所有底层数学都精通。地基课会给你『够用』的数学，不是研究生讲义。"]},{"type":"practice","quiz":[{"q":"下面的包含关系哪一个是正确的？","opts":["AI ⊃ LLM ⊃ Deep Learning ⊃ ML","AI ⊃ ML ⊃ Deep Learning ⊃ LLM","LLM ⊃ AI ⊃ ML ⊃ Deep Learning","Deep Learning ⊃ ML ⊃ AI ⊃ LLM"],"a":1,"explain":"AI 包含机器学习，机器学习包含深度学习，LLM 是深度学习上长出的一个具体模型——所以 AI ⊃ ML ⊃ DL ⊃ LLM。"},{"q":"ChatGPT 更像下面哪一个？","opts":["一个 Agent","一个纯 LLM 对话产品","一个 RAG 系统","一个视觉模型"],"a":1,"explain":"ChatGPT 的核心是大语言模型：你输入，它预测下一个词。RAG/Agent 是在它之上叠加的能力。"},{"q":"NotebookLM『查你上传的资料再回答』，主要用到了哪项技术？","opts":["RAG / 检索增强生成","纯预训练","强化学习","扩散模型"],"a":0,"explain":"针对私有资料，RAG 会让模型先去检索相关片段再做回答，这正是 NotebookLM 类产品的核心。"}]},{"type":"connection","known":["（这是第一节课，还没有前置知识）"],"learned":["AI → ML → DL → LLM 的主干链条","LLM 之外还有视觉 / 语音 / Agent / RAG 等方向","ChatGPT、Claude、Codex、NotebookLM 各自代表哪一类"],"next":"接下来你会先进入『向量与语义』：Embedding 是怎么把文字变成电脑能算的数字——这是理解 LLM 的第一块砖。"}]}],"c02-essentials":[{"id":"l-embedding","title":"Embedding｜怎么把词变成电脑能懂的数字","subtitle":"为什么文字不能直接进神经网络？为什么不是给每个词编个号？为什么意思相近的词离得更近？","category":"c02-essentials","chapterTitle":"第一章 · 向量与语义","level":"base","estTime":"20 分钟","difficulty":2,"concepts":["embedding","vector","cosine-similarity","emb-vector-store"],"prereqLessons":["l00-ai-world"],"nextLesson":"l-attention","sections":[{"type":"oneline","text":"Embedding 就是把『一个词』变成『一串数字（向量）』，并且让意思相近的词，数字串长得也相近——于是电脑就能『算』语义了。"},{"type":"why","before":"神经网络只会做数学运算：加、乘、比较大小。它天生看不懂文字『猫』『狗』『苹果』。","problem":"如果你根本没法把文字送进神经网络，那后面的一切（翻译、对话、理解）都是空中楼阁。这是所有语言模型的『第一道门』。","need":"所以我们必须在文字和数字之间搭一座桥。这座桥就是 Embedding。","visualNote":"先看一个最朴素的思路，再一步步升级到真正的 Embedding。"},{"type":"intuition","blocks":[{"k":"为什么不能直接给词编号？","t":"你可能会想：给猫=1、狗=2、苹果=3 不就行了？但问题是：2 和 3 只差 1，可『狗』和『苹果』的语义差得十万八千里。编号把『数字距离』和『语义距离』完全搞乱了。"},{"k":"用一张坐标纸来想","t":"想象一张二维地图，横轴是『是不是动物』，纵轴是『是不是食物』。『猫』放左边偏上，『狗』放它旁边，『苹果』放右上角。位置越近，意思越像。Embedding 本质就是在几百上千维的『坐标纸』上，给每个词找个位置。"},{"k":"一个生活类比","t":"就像地理坐标：北京和天津坐标很近，所以它们在空间上相邻；Embedding 也是给词一个『语义坐标』，语义相近的词坐标也相邻。"}]},{"type":"visual","kind":"embedding-space","title":"Embedding 2D 语义空间","hint":"这是把词『压扁』到二维的示意：意思相近的词会聚在一起。观察猫/狗/狮子聚在『动物角』，苹果/香蕉聚在『食物角』。"},{"type":"how","intro":"Embedding 是怎么『学』出来的？关键思想：一个词的含义 = 它经常和哪些词一起出现。","steps":[{"in":"收集大量文本","process":"从整个互联网 / 语料库里，观察『猫』总是和『狗、宠物、喵、毛』一起出现，而『苹果』总跟『水果、吃、红色』一起出现。","out":"得到每个词在语料里的『共现模式』"},{"in":"用共现模式训练向量","process":"训练算法会分配一组初始数字，然后不断调整，让『一起出现』的词向量越走越近，『从不一起出现』的词向量越走越远。","out":"每个词最终固定成一个向量（如 300 维数字）"},{"in":"用向量距离比较语义","process":"两个词的向量越接近（夹角越小 / 余弦相似度越高），语义越相近。","out":"电脑就能『算』出：猫≈狗，苹果≠猫"},{"in":"送入下游模型","process":"这个数字向量就是神经网络的输入。LLM 只认数字，现在它『看得懂』词了。","out":"模型能对词做运算、比较、生成"}]},{"type":"deep","beginner":["Embedding 是『查表』：模型里有一张巨大的表，每个词一行，那一行数字就是它的向量。训练好之后，直接用查到的数字。","维度越高，能表达的语义越细腻，但计算越贵。常见几百维就够用。"],"advanced":["向量不只是给每个词一个『标签』，它把语义结构编进了几何里：经典例子 king - man + woman ≈ queen，说明方向也承载意义。","Embedding 模型（如 text-embedding 系列）与 LLM 是不同模型：前者把文本压缩成‘定位码’，后者生成文字。它们可以分开训练、分开使用。",{"code":"# 概念示意：余弦相似度，越大越像\nimport numpy as np\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\ncat = np.array([0.9, 0.1])    # 靠近动物方向\napple = np.array([0.1, 0.9])  # 靠近食物方向\nprint(cosine(cat, apple))     # 结果小，说明语义远","lang":"python"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude","note":"内部第一件事就是把你的每个词 Token 转成 Embedding 向量，再送进 Transformer。"},{"name":"搜索引擎语义检索","note":"把『怎么养猫』和『养宠物指南』都向量化，语义相近就能匹配，不必字面相同。"},{"name":"NotebookLM / RAG","note":"把你的资料切成块并向量化，用户提问时在向量空间里『找最像的那几块』再交给模型回答。"}]},{"type":"compare","pairs":[{"a":"Token","b":"Embedding","diff":"Token 是文字切出的‘小块’（词/子词）；Embedding 是把每个小块变成的‘数字向量’。Token 决定切多细，Embedding 决定怎么算语义。"},{"a":"Embedding 模型","b":"LLM","diff":"Embedding 模型把文本压成‘定位向量’（不做对话）；LLM 生成文字。一个是‘编码员’，一个是‘作家’。"},{"a":"给词编号（One-hot）","b":"Embedding","diff":"编号让所有词距离相等、无法表达语义；Embedding 让相近的词距离更近，真正抓住了含义。"}]},{"type":"mistakes","items":["以为 Embedding 只是『给每个词一个数字』。其实是一整串数字（向量），且数字之间有序的相似关系。","以为 Embedding 模型和 LLM 是一个东西。它们是两个分工不同的模型。","以为向量维度越高一定越好。维度高表达力强但更贵、更易过拟合。","以为 Embedding 能理解逻辑。它只捕捉统计上的‘相似’，不保证逻辑正确。"]},{"type":"practice","quiz":[{"q":"为什么不能直接给每个词编个号（猫=1，狗=2）？","opts":["因为编号会让相近的词距离更近","因为编号会破坏语义距离：狗和苹果只差1，但语义差很远","因为编号需要太多内存","因为编号不能用于神经网络"],"a":1,"explain":"编号把‘数字距离’和‘语义距离’搞混了：只有编号差1的两个词会显得很近，但这和它们的含义无关。"},{"q":"两个 Embedding 向量‘夹角越小’，说明什么？","opts":["两个词的语义越相近","两个词的字符串越像","两个词出现频率越接近","两个词长度越接近"],"a":0,"explain":"夹角越小、余弦相似度越高，代表两个词在向量空间里越近，语义越相近。"},{"q":"关于 Embedding 模型与 LLM，正确的是？","opts":["它们是同一个模型","Embedding 模型把文本变向量，LLM 生成文字，二者分工不同","LLM 不做 Embedding","Embedding 模型能写文章"],"a":1,"explain":"Embedding 模型负责‘编码相似度’，LLM 负责‘生成内容’，是不同的模型。"}],"lab":{"title":"Mini Lab：2D 语义空间","desc":"在上方 Embedding 空间里，给新词拖一个位置，观察它和哪群已知词更近。体会‘位置=语义’这件事。","kind":"embedding-space"}},{"type":"connection","known":["AI 世界全景：模型只能处理数字"],"learned":["文字 → 向量，让电脑能算语义","相近的词向量距离更近，用余弦相似度衡量","Embedding 模型与 LLM 分工不同"],"next":"有了‘每个词是一个数字向量’，下一步就是大招：Attention——模型怎么在一句话里决定‘该重点关注哪个词’。再往前一步，你会看到 Transformer 如何把一堆向量变成会翻译、会聊天的大脑。"}]}],"c05-llm":[{"id":"l-attention","title":"Attention｜模型为什么知道该关注哪个词","subtitle":"当模型读到『它』，怎么知道是猫还是狗？为什么句子再长，模型也能把前后的词『对上号』？","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"20 分钟","difficulty":2,"concepts":["attention","qkv","multihead","attention-long"],"prereqLessons":["l-embedding"],"nextLesson":"l-transformer","sections":[{"type":"oneline","text":"Attention 是这样一种机制：模型在理解某个词时，会『回头看一眼』句子里的每一个词，并给它们分别打一个权重分——分数越高的词，模型花越多『注意力』在它身上。于是『它』到底指猫还是狗，模型有了办法分清。"},{"type":"why","before":"上节课我们把每个词变成了向量。但词是孤立的：『猫』『追』『狗』『它』，每一个都只是单独的一个数字串。","problem":"真正的语言是互相指代的。『猫追狗，它跑得飞快』——这个『它』是谁？只看『它』这个词本身，根本答不上来。更糟的是：以前的模型看长句时，越靠前的词就越『记不清』。","need":"我们需要一个机制：在处理任何一个词时，能直接『回看』整句话里的所有词，按『相关程度』加权吸收它们的信息。这就是 Attention——『注意力』。","visualNote":"下面你可以亲手造一句中文，点任何一个词，看它把注意力分给了谁。"},{"type":"visual","kind":"attention-heatmap","title":"Attention 热力图：点一个词，看它关注谁","hint":"输入一句话，点任意一个词（比如那棵/那株），热力图会显示这个词对其它词的『关注权重』——颜色越深，越关注。体型/量词线索会让权重自动偏向正确的词。"},{"type":"intuition","blocks":[{"k":"老师点名：每个词都是老师","t":"把模型想象成在逐一『审问』句子里的每个词。读到『它』这个词时，模型其实在问：『谁能告诉我『它』指谁？』——它会把问题抛向所有词，然后听答案最相关的那几个。"},{"k":"查字典：不是顺序读，而是跳着看","t":"Attention 最反直觉的一点：它不是老老实实从左往右读。读到『它』，它像翻开一本字典快速扫过所有词条，直接锁定『猫』『跑』这些词，记下『我主要靠这几个词来理解自己』。"},{"k":"聚光灯：每个词都有无数盏灯","t":"句子里每个词都举着一盏聚光灯照向其它词。灯越亮，代表『我理解你时越依赖你』。Attention 就是计算这盏灯亮度的过程。"}]},{"type":"how","intro":"Attention 到底怎么『算』注意力？核心就四步：每个词同时扮演三个角色——Query（我找谁）、Key（我是谁）、Value（我的内容）。","steps":[{"in":"乘上三个矩阵，得到 Q / K / V","process":"每个词的向量，分别乘以三个不同的矩阵，变成三个新向量：Query『我要去匹配谁』、Key『我是谁，请拿我来匹配』、Value『我的有效内容』。","out":"单词 → (Query, Key, Value) 三件套"},{"in":"用 Query 和所有 Key 算相似度","process":"以『它』的 Query 为例，和句子里每个词的 Key 做点积（就是 Embedding 课学过的‘方向越像越接近’）。","out":"得到一个分数列表：它 vs 猫 = 高分，它 vs 跑 = 中等……"},{"in":"Softmax 归一化成权重","process":"把所有分数经过 softmax，变成『加起来等于 100%』的权重。这一步保证了分数变成可比的概率。","out":"注意力权重：猫 0.6、跑 0.25、飞快 0.15……"},{"in":"用权重 × Value 加权求和","process":"把每个词的 Value 乘上它对应的权重再全部相加。权重大的词，它的内容在结果里占的份量就大。","out":"『它』经过处理后的新向量 = 主要吸收了『猫』的信息"},{"in":"每个词同时做，得到上下文向量","process":"句子里每个词都执行同样一套操作，得到一批『结合了全局上下文的新向量』。","out":"整个句子从一串孤立向量 → 一串互相理解的向量"},{"in":"多个头并行（多头注意力）","process":"为了不只从一种角度看，模型并行做多组 Q/K/V（不同随机初始化的矩阵），相当于多个不同视角同时观察。","out":"一个头看‘指代关系’，另一个头看‘语法结构’，再一个看‘长度’……"}]},{"type":"deep","beginner":["注意力权重加起来是 1（100%）。Softmax 就是把一坨分数变成「加起来为 1、且大的更大」的数。","不用纠结矩阵怎么算：你只需要记住『Query 找人，Key 被找，Value 是内容，三者相乘加权求和』这句话。","它最厉害的地方：任意两个词无论隔多远都能直接相关——远处那个词和眼前这个词，算注意力的成本完全一样。"],"advanced":["核心公式：Attention(Q, K, V) = softmax(Q·Kᵀ / √d) · V。除以 √d（d 是向量维度）是为了防止点积过大把 softmax 压死（梯度消失）。","Self-Attention：Q/K/V 都来自同一句话，让句子内部互相理解；Cross-Attention：Q 来自一方，K/V 来自另一方（例如翻译时译文找原文的对应）。","复杂度是 O(n²)：n 个词两两都算一遍。这正是上下文窗口成为瓶颈的原因——也是大家研究稀疏注意力、局部注意力的动机。","不要神化注意力可视化：权重高≠模型真『懂』了。它更多是统计相关，不是可解释的因果。",{"code":"# 概念示意：手工算一次注意力（2 个词的极简版）\nimport math\n\ndef softmax(xs):\n    ex = [math.exp(x) for x in xs]\n    s = sum(ex)\n    return [e / s for e in ex]\n\nq = [1.0, 0.0]  # 我是『它』的 Query\nks = {\"猫\": [0.9, 0.1], \"狗\": [0.2, 0.8]}  # 两个词的 Key\n\nscores = {w: round(q[0]*k[0] + q[1]*k[1], 3) for w, k in ks.items()}\nprint(\"点积分数:\", scores)\nweights = dict(zip(scores, softmax(list(scores.values()))))\nprint(\"softmax 权重:\", {w: round(v,3) for w,v in weights.items()})","lang":"python"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude 生成每个词","note":"每生成一个 token，模型都要对上下文做一次 Attention：决定下一个词『更依赖』前面的哪部分。"},{"name":"翻译模型的对齐","note":"把『I love you』翻译成中文时，Attention 会自动让『love』和『爱』『对上号』，哪怕位置完全错开。"},{"name":"代码补全","note":"模型补全函数体时，Attention 帮它『盯住』几千行前的函数签名和参数定义，而不是只看到最近几行。"},{"name":"长文档问答","note":"你在长文章里问『第三部分的结论是？』，Attention 让模型跳过大段无关内容，直接聚焦第三部分的句子。"}]},{"type":"compare","pairs":[{"a":"RNN 顺序处理","b":"Attention 全局直连","diff":"RNN 必须一个字一个字按顺序传，远处信息会衰减；Attention 任意两个位置直接相联，没有距离衰减。"},{"a":"Self-Attention","b":"Cross-Attention","diff":"Self 是同句话内部互相理解；Cross 是让一方去『读』另一方（翻译、RAG 上下文注入都用它）。"},{"a":"单头注意力","b":"多头注意力","diff":"单头只有一种‘看法’；多头并行多组 Q/K/V，相当于同时用多个角度理解，效果明显更好。"}]},{"type":"mistakes","items":["以为 Attention 是『看一遍就记住』的长期记忆。它不是记忆，而是每次计算时动态分配的关注权重——注意力要重新算，不会存下来。","以为注意力可视化等于模型的可解释性。权重高代表统计上相关，不代表模型逻辑上『是因为这个』。","把『注意力』和『上下文窗口』混为一谈。窗口决定能看多远，Attention 决定窗口内怎么分配关注。","以为只看『最近几个词』。Attention 恰恰是全局的——它牺牲计算量换来的是真正看全上下文。"]},{"type":"practice","quiz":[{"q":"Attention 中，Query、Key、Value 各自的作用最准确的说法是？","opts":["Q 是内容，K 是找人，V 是被找","Q 在找人，K 是被找的标签，V 是被吸收的内容","三者完全相同","Q 是权重，K 是分数，V 是标签"],"a":1,"explain":"Q（Query）发起匹配→去找谁；K（Key）告诉别人『我是谁』、供匹配；V（Value）是被吸收进结果的真正内容。"},{"q":"为什么说 Attention 解决了 RNN『记不住长句』的问题？","opts":["因为它是顺序处理的","因为任意两个词都可以直接相关，不随距离衰减","因为它把句子变短了","因为它只关心最近的词"],"a":1,"explain":"RNN 依赖顺序传递，距离远信息衰减；Attention 让任意两个位置直接相连，远近一视同仁。"},{"q":"把注意力分数做 softmax 是为了？","opts":["让负数变成正数","让分数变成加和为 1 的权重，且强调大的","让计算更快","让向量变短"],"a":1,"explain":"Softmax 把一坨任意分数变成『加起来为 1』、且大者更大的概率分布，这样加权求和才合理。"}],"lab":{"title":"Mini Lab：亲手算一次 Attention","desc":"在上方热力区输入你的一句话，点不同词观察权重分配；再试试把量词改掉，体会权重如何跟着语义线索移动。","kind":"attention-heatmap"}},{"type":"connection","known":["词 → 向量（Embedding）","向量方向越像、语义越近（余弦相似度）"],"learned":["每个词同时是 Query / Key / Value","注意力 = 相似度分数 → softmax 权重 → 加权求和","Self-Attention 让句子内部互相理解，多头提供多视角"],"next":"Attention 是 Transformer 的心脏。下一课我们会看到：怎么把这一套注意力，组装成一个能真正训练、能翻译能写诗的完整大模型架构——Transformer。再往后，你会明白 RAG 和 Agent 都是在这个架构上叠出来的能力。"}]},{"id":"l-transformer","title":"Transformer｜大模型的地基架构","subtitle":"为什么 2017 年诞生的它，能横扫翻译、写作、代码、对话？一个 20 分钟看懂『大模型的心脏是怎么拼出来的』。","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"25 分钟","difficulty":3,"concepts":["transformer","position-enc","multihead","attention"],"prereqLessons":["l-attention"],"nextLesson":"l-rag","sections":[{"type":"oneline","text":"Transformer 是 2017 年提出的一个『把注意力机制组装成完整大脑』的架构：它用『多头注意力 + 前馈网络 + 残差连接 + 位置编码』堆成一叠一层又一层的模块，能并行、能训练得非常深，从此成为 ChatGPT、Claude、Gemini 的共同地基。"},{"type":"why","before":"上一课我们有了 Attention：任何两个词都能直接互相关注。但这只是一块『积木』，离一个能真正工作的模型还差很远。","problem":"只靠 Attention 还不够：1) 它不知道词的位置——『猫追狗』和『狗追猫』词全一样；2) 一层注意力学到的东西有限；3) 堆深了又容易训练不动。","need":"Transformer 就是给 Attention 配上『位置感、深度、稳定训练的装备』，把一块积木组装成一台可训练的机器。","visualNote":"下面这张图是 Transformer 的主干流水线，你可以一步一步点开看每一层在干什么。"},{"type":"visual","kind":"transformer-flow","title":"Transformer 主干流水线：一步一步看","hint":"点击【下一步】，观察一个词从『数字向量』走到『预测下一个词』的完整过程：输入 → 位置编码 → 多头注意力 → 残差+归一化 → 前馈网络 → 重复堆叠 → 输出。"},{"type":"intuition","blocks":[{"k":"一个加工厂流水线","t":"把 Transformer 想成一家加工厂：原料是一串向量。每个工位（层）做两件事——同事协作（注意力，大家互通信息）＋ 个人精加工（前馈网络，每个词独自想更深）。一层做完送下一层，共 N 层。"},{"k":"用乐高积木来想","t":"Attention 只是其中一块积木。Transformer 是说明书：告诉你『这一层要怎么拼：注意力 + 残差 + 归一化 + 前馈；然后复制粘贴 N 次』。"},{"k":"办公室里的并行会议","t":"RNN 像只有一个话筒的圆桌，每人必须轮流说（慢）；Transformer 像微信群——所有人同时发言、同时收听（并行快），谁跟谁相关自己匹配（注意力）。"}]},{"type":"how","intro":"一个词在 Transformer 里的完整旅程。每一步都围绕同一批向量做变换，最后模型学会『预测下一个词』。","steps":[{"in":"输入：词向量 + 位置编码","process":"每个词先查表得到 Embedding 向量。但向量本身不含『位置』，所以再加一个位置信息（位置编码），让模型知道『这是第 5 个词』。","out":"每个词带上位置的向量"},{"in":"多头注意力层（同事协作）","process":"这一层让每个词结合全局上下文：用上节课的 Q/K/V 机制，多组并行，每组的输出再拼接。词的『含义』从此包含了周围所有词。","out":"每个词变成『理解上下文后的新向量』"},{"in":"残差连接 + 归一化（稳定训练）","process":"把『进来的向量 + 注意力算完的向量』加在一起（残差），再做归一化。这就像修了一条高速公路：信息不衰减地直接流过深层。","out":"浅层信息可以无损‘抄近道’到达深层，网络能堆得深"},{"in":"前馈网络 FFN（个人精加工）","process":"一个两层全连接网络，对每个词独立再做非线性变换，让模型有能力表达更复杂的关系。","out":"每个词被‘再想一想’，表达能力增强"},{"in":"重复堆叠 N 层","process":"把『注意力 + 残差 + 归一化 + 前馈』这组动作复制 N 次叠起来（GPT 有十到上百层）。每层都让词的表示更抽象、更接近任务。","out":"深层的向量已经‘浓缩’了整句话的语义"},{"in":"输出：预测下一个词","process":"最后一层接一个线性层 + softmax，把向量变成『词典里每个词的概率』，模型取概率最高的作为下一个词。","out":"生成一个词 → 拼回输入 → 继续预测下一个词"}]},{"type":"deep","beginner":["位置编码就是给每个词加个『第几个』的记号，否则『猫追狗↔狗追猫』对模型来说字全一样。","残差连接简单说就是『进来和出去加一起』，像搭桥——让深层的梯度不会消失，模型才能堆数十上百层。","前馈网络 FFN 是给每个词单独『换个角度想一遍』，和注意力（词与词协作）分工不同、缺一不可。","GPT 其实只用了 Transformer 的一半：只有『解码器』那套（Decoder-only），用来不停地预测下一个词。"],"advanced":["核心是 Decoder：每个 token 只看自己和前面（因果掩码 causal mask），保证预测时不‘偷看’未来。这是它和编码器最大区别。","缩放点积注意力公式：Attention = softmax(QKᵀ/√d)V。除以 √d 防点积过大导致梯度消失/softmax 饱和。","三种架构：Encoder-only（BERT：理解）、Decoder-only（GPT：生成）、Encoder-Decoder（T5：翻译/转换）。ChatGPT 系清一色 Decoder-only。","残差连接 + LayerNorm（Pre-LN 顺序）是训练稳定性的关键工程细节，是让它能堆到千亿参数的原因之一。","复杂度 O(n²)：上下文窗口越大成本越高——这直接决定了『长上下文为什么贵』『为什么要 RAG』。",{"code":"# 概念示意：位置编码的经典公式（不必实现，体会它想表达什么）\nimport math\n\ndef pos_encoding(pos, d_model=8):\n    # 给第 pos 个词生成 d_model 维的位置向量，奇偶通道分别用 sin/cos\n    vec = []\n    for i in range(d_model):\n        angle = pos / (10000 ** (2 * (i // 2) / d_model))\n        vec.append(round(math.sin(angle), 3) if i % 2 == 0 else round(math.cos(angle), 3))\n    return vec\n\nfor p in [0, 1, 2, 3]:\n    print(f\"第{p}个词的位置: {pos_encoding(p)}\")","lang":"python"}]},{"type":"realworld","items":[{"name":"ChatGPT / GPT 系列","note":"Decoder-only Transformer：单纯地、一层层地预测下一个词，就长出了对话和推理能力。"},{"name":"Claude / Gemini","note":"同一架构的不同工程实现：同样的多头注意力 + 深层堆叠，在尺度与训练技巧上各有差异。"},{"name":"翻译与摘要模型（T5/BART）","note":"Encoder-Decoder 结构：编码器读懂全文，解码器再一句句生成译文或摘要。"},{"name":"代码补全（Codex 前身 CodeGPT）","note":"把代码当‘另一种语言’喂给 Decoder-only Transformer，学会了补全、续写、改 bug。"}]},{"type":"compare","pairs":[{"a":"RNN","b":"Transformer","diff":"RNN 顺序串行、远处信息衰减、难并行；Transformer 全局直连、天然并行、能堆深。2017 后几乎完全取代 RNN。"},{"a":"Encoder-only（BERT）","b":"Decoder-only（GPT）","diff":"前者双向读全文、擅长‘理解’（分类/检索）；后者只能从左往右、擅长‘生成’（对话/写作/代码）。"},{"a":"单层注意力","b":"N 层堆叠的 Transformer","diff":"单层只做一次‘互相看’；Transformer 把多次‘互相看+精加工’叠起来，让表示一层比一层抽象。"}]},{"type":"mistakes","items":["以为『Transformer = Attention』。Attention 只是其中的一个子模块，完整架构还包括残差、归一化、前馈、位置编码。","以为 BERT 和 GPT 一样。BERT 双向理解、GPT 单向生成，职权完全不同。","以为层数越多一定越好。层越深效果提升有边际，还会带来更大的算力和训练难度。","把『位置编码』当可选项。没有它，『猫追狗』和『狗追猫』对模型来说完全一样——这可是天壤之别。"]},{"type":"practice","quiz":[{"q":"为什么 Transformer 需要位置编码？","opts":["为了让向量维度变大","因为注意力本身不含位置信息，没有位置编码『狗追猫』和『猫追狗』无法区分","为了加快计算","为了让训练更快收敛"],"a":1,"explain":"注意力是把所有词互相加权，天然『不记得顺序』；位置编码把‘第几个’注入向量，模型才知道顺序。"},{"q":"残差连接（Residual）的主要作用是？","opts":["增加参数数量","让信息能无损跨层传递，网络可以堆得很深且训练稳定","让模型更快生成","代替位置编码"],"a":1,"explain":"把输入和输出相加，像搭桥一样让信息直达深层，缓解深层网络的梯度消失，是能堆几十上百层的关键。"},{"q":"GPT 属于哪种结构？","opts":["Encoder-only","Decoder-only","Encoder-Decoder","既不是编码器也不是解码器"],"a":1,"explain":"GPT 只用解码器（带因果掩码、从左往右生成），反复预测下一个词。"}],"lab":{"title":"Mini Lab：走一遍 Transformer 流水线","desc":"在上方流水线里逐步播放，观察同一个词每经过一层，它的『表示』如何从字面向量变成富含上下文的向量，最后被用来预测下一个词。","kind":"transformer-flow"}},{"type":"connection","known":["Attention：Q/K/V 加权求和，让词与词互相关注","词是向量，语义可算相似度"],"learned":["Transformer = 多头注意力 + 残差 + 归一化 + 前馈网络的 N 层堆叠","位置编码让模型感知顺序","GPT 是 Decoder-only，靠预测下一个词长出能力"],"next":"Transformer 有了，模型『什么都会但只记得训练时的知识』。下一课我们解决这个关键问题：RAG —— 怎么让模型在回答前先去『你的资料库』查资料，从而回答它没学过的私有内容。"}]}],"c07-rag":[{"id":"l-rag","title":"RAG｜让模型『查资料』再回答","subtitle":"为什么 ChatGPT 不知道你的私有文档？怎么让模型『翻开你的资料』再回答？从切块到生成，一条流水线看懂 RAG。","category":"c07-rag","chapterTitle":"第一章 · RAG 全流程","level":"base","estTime":"25 分钟","difficulty":2,"concepts":["rag-pain","rag-pipeline","chunking","emb-vector-store","vector-search","rerank"],"prereqLessons":["l-transformer","l-embedding"],"nextLesson":"l-agent","sections":[{"type":"oneline","text":"RAG（检索增强生成）就是：让模型在回答之前，先去你的资料库里『检索』相关的内容，把查到的片段拼进上下文，再让模型『照着资料』作答。于是它能回答自己『没学过』的私有知识，还能顺便指出出处。"},{"type":"why","before":"经过前面几课，我们已经有了一个很聪明的模型（Decoder-only Transformer）。但它有一个致命限制：它只知道『训练时见过的东西』，而且经常一本正经地编造（幻觉）。","problem":"1) 你的合同、内部 SOP、论文——模型训练时根本没见过；2) 即使见过，版本也过期了；3) 让它硬答私有问题，它大概率会编。重新训练整个模型又贵又慢。","need":"与其改模型的『脑子』，不如每次回答时给它配一本『说明书』：先把相关的资料找出来喂给它。这个思路就是 RAG，简单、便宜、可随时更新。","visualNote":"下面这条流水线是 RAG 的完整精神：切块 → 向量化 → 检索 → 重排 → 组装 → 生成。你可以一步步看。"},{"type":"visual","kind":"rag-pipeline","title":"RAG 完整流水线：从文档到回答","hint":"逐步播放：上传文档 → 切块 Chunk → 向量化 Embedding → 存入向量库 → 用户提问 → 检索 Top-K → 重排 Rerank → 组装上下文 → 生成回答（带引用）。每一步都点开看细节。"},{"type":"intuition","blocks":[{"k":"开卷考试 vs 闭卷考试","t":"普通 LLM 是闭卷考试：只凭脑子里的记忆答题，记不住就编。RAG 是开卷考试：允许先翻资料，翻到相关的那页再答。显然开卷更可靠。"},{"k":"图书馆查书再回答","t":"你问『公司年假制度是什么』。RAG 不会直接在记忆里编，而是先去公司知识库『检索』年假相关文档，找到后引用着回答。"},{"k":"不是变聪明，是带了参考书","t":"RAG 不提升模型智商，而是每次回答都『带着最新的、属于你的资料』。资料更新，回答立刻跟着更新，不用重新训练。"}]},{"type":"how","intro":"RAG 分两个阶段：『入库』（离线，把文档变成可检索的向量库）和『查询』（在线，用户提问时检索+生成）。下面是完整流程。","steps":[{"in":"为什么需要 RAG（先想清楚）","process":"场景：需要回答私有/最新/超长知识，或需要答案可溯源。如果模型自带答案且内容不敏感，RAG 可能不是最优选。","out":"想清楚：RAG 解决的是『知识更新与私有化』，不是『模型变聪明』"},{"in":"切块 Chunking","process":"把长文档（PDF/网页）切成几百上千字的小块。切多大、是否重叠、按什么切（标题/段落）会直接影响检索质量。","out":"文档 → 若干 chunk（带元数据：来源、页码）"},{"in":"向量化 Embedding","process":"用 Embedding 模型把每个 chunk 变成一个向量（上上节课学的：文字 → 数字，语义相近的向量相近）。","out":"每个 chunk → 一个向量"},{"in":"存入向量库 VectorDB","process":"把『向量 + 原文 + 元数据』一起存进向量数据库（如 FAISS、Milvus、pgvector），并建好索引以便快速搜索。","out":"可毫秒级完成相似检索的向量库"},{"in":"检索 Retrieval","process":"用户提问时，把问题也向量化，然后在向量库里找『最像的 Top-K 块』（一般是余弦相似度排名）。","out":"问题 → 找出最相关的 N 个 chunk"},{"in":"重排序 Rerank","process":"初筛的 Top-K 可能不够准。用一个更精细的模型把这 K 个再排一次，把真正相关的提到最前、过滤掉噪音。","out":"更精准的候选（通常是前 3~5 块）"},{"in":"组装上下文","process":"把检索到的 chunks 拼进 Prompt，附上用户问题，并提示模型『只依据下面的资料回答，引用出处』。","out":"一份带参考资料的完整 Prompt"},{"in":"生成 Generation","process":"LLM 基于这份『资料 + 问题』生成回答，并标注引用了哪一段。","out":"有出处、可更新、针对私有知识的回答"}]},{"type":"deep","beginner":["chunk 太小：语义不完整；chunk 太大：噪音多、还可能被截断。常见几百~一千字 + 20% 重叠。","向量相似≠字面相似：改个说法（『年假』 vs 『带薪假期』）有时也能检索到，这是向量检索比关键词厉害的地方。","RAG 不会凭空创新知识，它只会『引用你给的东西』——所以资料库质量≈回答质量。"],"advanced":["混合检索（Hybrid）：向量检索（语义）+ 关键词检索（BM25，精确匹配人名/编号）结合起来，互补漏检。","Rerank 为什么必要：初检向量健壮但不够精，专门的 rerank 模型（cross-encoder）能逐对精判相关性，显著提升准确率。","引用溯源（Citation / Grounding）：让模型输出时带上片段编号，用户能核对来源，也是落地合规的关键。","GraphRAG 等进阶：把实体关系建成图结构检索，适合『要跨多个文档推理』的难题。","评估：召回率（该找到的找到没）与准确率（找到的是不是都相关），以及最终回答的有据率。",{"code":"# 概念示意：RAG 里最核心的一步——向量检索（伪代码思路）\nimport numpy as np\n\n# 假设我们已经把文档块向量化并存在 chunks 里\nchunks = [\"年假制度：入职满一年享 5 天…\", \"报销流程：金额低于 1000 走 OA…\"]\nchunk_vecs = [np.array([0.9, 0.1]), np.array([0.1, 0.9])]  # 示意向量\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\nquery_vec = np.array([0.85, 0.15])  # 用户问题『年假有几天』向量化\nscores = sorted(((cosine(query_vec, v), i) for i, v in enumerate(chunk_vecs)), reverse=True)\ntop1 = chunks[scores[0][1]]\nprint('最相关的资料块:', top1)  # → 年假制度那一段","lang":"python"}]},{"type":"realworld","items":[{"name":"NotebookLM","note":"你上传 PDF/视频，它检索你的资料再回答，还能生成带引用的播客、摘要。教科书级 RAG 产品。"},{"name":"企业内部知识库客服","note":"把 SOP、产品手册向量化，客服 AI『查文档再回答』，而不是对着空气编。"},{"name":"Claude Projects / 附件上传","note":"给对话挂上资料，模型按需检索引用，本质是一套轻量 RAG。"},{"name":"搜索增强的 ChatGPT / Perplexity","note":"它先联网检索实时网页，再基于检索结果回答——也是 RAG（用 web 当『向量库』）。"}]},{"type":"compare","pairs":[{"a":"RAG","b":"微调 Fine-tuning","diff":"RAG 每次查最新资料、可溯源、便宜、可随时更新；微调是改模型‘脑子’、更像学风格学格式。知识类更新首选 RAG。"},{"a":"向量检索","b":"关键词检索","diff":"向量找‘语义相近’（换个说法也能找到）；关键词精准匹配字面（找人名编号更稳）。生产常用混合。"},{"a":"RAG","b":"超长上下文","diff":"RAG 主动挑最相关片段、便宜快速；超长上下文把整本书塞进去、贵且容易‘淹没’重点。大库优先 RAG。"}]},{"type":"mistakes","items":["以为 RAG = 把文档一股脑塞进提示词。真正的 RAG 要先切块、向量化、检索、重排，只喂最相关的几块。","忽略 chunking 质量。切坏了，再好的模型也答不准——检索进来自的都是垃圾。","以为检索到就完了，不做 rerank。初检的 Top-K 常有噪音，重排能明显提高准确率。","忘记引用溯源。落地到严肃场景（医疗/法务/企业），没有出处等于不可信。","把 RAG 当成解决幻觉的万灵药。资料里没有或检索失败时，模型照样可能编。"]},{"type":"practice","quiz":[{"q":"RAG 解决的核心问题是？","opts":["让模型数学更好","让模型能回答私有/最新知识并可溯源，而不用重新训练","让模型更快生成","让模型学会编程"],"a":1,"explain":"RAG 的核心价值：用检索到的外部资料补充模型没学过的知识，便宜、可更新、可引用。"},{"q":"RAG 的『入库』阶段，正确的顺序是？","opts":["向量化 → 切块 → 存库","切块 → 向量化 → 存库","存库 → 向量化 → 切块","检索 → 切块 → 向量化"],"a":1,"explain":"先把长文档切成 chunk，再逐块向量化，最后连向量带原文存进向量库。『检索』是查询阶段的事。"},{"q":"为什么生产系统里还要做 Rerank 重排？","opts":["为了多花一点算力","初检的 Top-K 常有噪音，用更精细的模型重排能显著提升相关性与准确率","为了把回答变长","为了跳过 embedding"],"a":1,"explain":"向量初检健壮但不精，专门的 rerank 模型能逐对精判，把真正的相关片段提到最前。"}],"lab":{"title":"Mini Lab：走一遍 RAG 全流程","desc":"在上方流水线逐步播放：看一份文档如何被切块、向量化、检索、重排，最终变成一次带引用的回答。理解每一步在哪犯了错会怎样。","kind":"rag-pipeline"}},{"type":"connection","known":["Embedding：文字 → 向量，语义相近的向量相近","Transformer：模型的‘脑子’","上下文窗口：模型一次能看多少"],"learned":["RAG 让模型先检索资料再回答，解决私有/最新/可溯源","完整流程：切块 → 向量化 → 向量库 → 检索 → 重排 → 生成","RAG vs 微调 vs 长上下文 的取舍"],"next":"RAG 让模型『会查资料』，但模型还是停在『你说一句、它应一句』。下一课是这个旅程的终点也是新起点：Agent —— 让模型自己拆目标、自己动手调用工具，把一整件事做完。"}]}],"c08-agent":[{"id":"l-agent","title":"Agent｜让 AI 自己动手做事","subtitle":"为什么 ChatGPT 只能在对话框里打字，而 Codex 能改你的代码、跑你的测试、提交 PR？Agent 就是把『会说话』的模型，变成『会做事』的执行者。","category":"c08-agent","chapterTitle":"第一章 · 从会说到会做","level":"base","estTime":"25 分钟","difficulty":2,"concepts":["agent-intro","agent-loop","tool-use","agent-planning","agent-memory","agent-reflection"],"prereqLessons":["l-rag","l-transformer"],"nextLesson":"l22-ai-coding","sections":[{"type":"oneline","text":"Agent（智能体）不是换个厉害的模型，而是给模型装上一个『决策循环』：它会自己拆目标、自己调用工具（读写文件、执行代码、搜网页）、观察结果、再决定下一步，如此循环直到把事情做完。同样一个模型，套上这个循环，就从『只会回答』变成了『会做事』。"},{"type":"why","before":"到这一课，我们有了很聪明的模型、也有了让它『查资料』的 RAG。但你还是有个困扰：让 ChatGPT 整理个表格它倒是能，让它『去我仓库里改掉那个 bug』，它做不到。","problem":"因为聊天模型只有一张『嘴』：它只能输出文字，看不见你的文件、读不了你的代码、跑不了测试命令。你让它『操作仓库』，它连仓库在哪都不知道。","need":"Model（思考）+ Tools（手和眼）+ Loop（循环驱动）= Agent。它想一下 → 动一下 → 看一眼结果 → 再想 → 再动。这就是 ChatGPT 和 Codex 的分水岭。","visualNote":"下面这个循环图就是 Agent 的灵魂——你可以点每一步看它到底在干什么。"},{"type":"visual","kind":"agent-loop","title":"Agent 循环：想 → 做 → 看 → 再想","hint":"逐步播放一个 Agent 修复 bug 的完整循环：理解目标 → 拆计划 → 调用工具（读代码/改代码/跑测试）→ 观察结果 → 陷入失败 → 修正 → 完成并交付。"},{"type":"intuition","blocks":[{"k":"计算器只会算，助理会办事","t":"普通聊天模型像一台高级计算器：你问它答。Agent 像你的助理：你交代一件事，它自己拆步骤、打电话（调工具）、核对结果，办完给你汇报。"},{"k":"不是变聪明，是变『能动』","t":"它没有比 ChatGPT 更聪明——它只是多了一圈『能动手、能看反馈、能再试』的回路。代码还是那个代码，差别在于它学会了『执行-反馈-调整』。"},{"k":"交给你手里没钥匙的实习生 vs 有钥匙的实习生","t":"ChatGPT 是没钥匙的实习生：看到门（需要改文件）只会描述『你应该去改那个文件』。Agent 是有钥匙的实习生：自己开门、改文件、跑测试、看结果、再改。"}]},{"type":"how","intro":"一个 Agent 改 bug 的完整工作过程。核心就一句话：目标 → 循环（想 + 做 + 看）→ 交付。","steps":[{"in":"理解目标","process":"用户下达：『修好注册页面的 bug』。模型先把模糊目标翻译成具体子任务列表。","out":"一个可执行的任务清单"},{"in":"规划 Planning","process":"它推理出步骤：先找到注册页代码 → 读源码定位问题 → 想怎么改 → 改 → 跑测试验证。","out":"Agenda：找代码 / 读 / 改 / 测"},{"in":"调用工具 Tool Use（Act）","process":"它请求调用工具：read_file 读代码、edit_file 修改、run_command 跑测试。工具返回结果。","out":"一次具体的‘动手’"},{"in":"观察结果 Observe","process":"看到工具返回值：测试报错，或编译失败。它读到反馈，判断是否达到目标。","out":"对‘刚才做的事情对不对’的感知"},{"in":"循环 Loop：再想再做","process":"若未达成，回到‘想’：根据报错调整方案，再调用工具。如此循环直到测试通过或放弃。","out":"反复的 agent loop（这正是和 ChatGPT 的本质区别）"},{"in":"交付与汇报","process":"任务完成：向用户总结改了什么、测试结果，甚至主动提交 PR、申请权限。","out":"一件完成的事，而不是一段话"}]},{"type":"deep","beginner":["Agent Loop 不是魔法：本质就是模型的 for/while 循环——决定下一步 → 调用工具 → 看结果 → 决定再下一步。","工具（Tool）就是『一个函数』：read_file、write_file、run_command、web_search。模型学会了在合适时机调用它们。","最朴素的 Agent = LLM + 工具集 + 一个决定何时停止的循环。它也可以有记忆和规划，但核心就是这个循环。"],"advanced":["Tool Use / Function Calling：模型输出结构化的『要调用哪个函数、传什么参数』，由系统执行并把结果喂回去，形成闭环。","记忆分两层：短期（当前任务的对话/工具历史）与长期（跨对话的项目知识、偏好，常存向量库）。","Planning 范式：ReAct（Reason + Act 交替）、Plan-and-Execute（先定计划再逐步执行、plan 可被动态修订）。","权限与安全 Permission：Agent 不会无限乱来——危险操作（删文件、花钱、外发数据）要求用户授权（approval gate）。","MCP（Model Context Protocol）：统一『工具/数据源』接入协议，让一个 Agent 能标准化接入文件系统、数据库、浏览器等多种工具，避免每家写一套私有接口。","Reflection 反思：让 Agent 回顾刚才失败的原因再调整，显著提升长任务的可靠性。多 Agent 协作则是多个专业 Agent 分工。",{"code":"# 概念示意：Agent 循环的骨架，就长这样\nwhile not goal_reached:\n    thought = model.think(state, memory)      # 想：我要做哪一步？\n    if thought.should_stop: break              # 判断是否完成\n    tool_result = call_tool(thought.tool_call) # 做：调用工具\n    state.append(tool_result)                  # 看：把结果存进上下文\n    memory.update(state)                       # 记住教训\n# 交付\nreport(model.summarize(state))","lang":"python"}]},{"type":"realworld","items":[{"name":"Codex / Claude Code","note":"Agentic Coding 的典型：能读你的仓库、找 bug、改代码、跑测试、提交 PR。这就是『ChatGPT 做不到、它做得到』的原因——它装了代码工具 + agent loop。"},{"name":"Cursor / Windsurf","note":"IDE 里的 Agent：理解整个项目上下文，跨多个文件完成重构，而不只是一行行补全。"},{"name":"浏览器 Agent（如 Browser Use / Operator）","note":"自己打开网页、读取、点击、填表，把『逛网页办事』自动化。"},{"name":"n8n / 工作流编排","note":"让 Agent 串联多个工具/API 完成端到端业务流程（取数→处理→发通知）。"}]},{"type":"compare","pairs":[{"a":"Chatbot（聊天机器人）","b":"Agent（智能体）","diff":"Chatbot 只输出文字、终结于回答；Agent 拆目标、调工具、看结果、循环迭代，终结于『做成事』。"},{"a":"单次工具调用","b":"多步 Agent Loop","diff":"可以调一个工具的助手只是初级；真正的 Agent 会根据结果决定下一调用，持续多轮直到完成。"},{"a":"RPA（脚本化机器人）","b":"LLM Agent","diff":"RPA 按写死的剧本执行、一变就崩；Agent 动态推理、能处理没见过的异常情况。"}]},{"type":"mistakes","items":["以为 Agent 只是『换了个更聪明的模型』。本质差别在『循环 + 工具』，不是模型本身。","以为 Agent 能无限可靠地自主执行。它也会反复失败、会犯错，所以需要权限门槛（approval gate）、观测和护栏。","忽视权限与安全。放任 Agent 删文件/发数据/花钱是最危险的坑，生产环境必须加授权与审计。","把『会调用工具』当成『有规划和反思』。会调一个函数 ≠ 会拆解复杂目标并自我修正，后者才是 Agent 的进阶。","以为多 Agent 一定更好。多数场景单 Agent 更简单可控，盲目堆 Agent 只会带来编排复杂度和成本。"]},{"type":"practice","quiz":[{"q":"为什么 ChatGPT 不能操作你的仓库，而 Codex 可以？","opts":["因为 Codex 模型更聪明","因为 Codex 被接上了工具（读写文件/跑命令）+ Agent 循环，ChatGPT 只有对话输出","因为 ChatGPT 没联网","因为模型大小不同"],"a":1,"explain":"决定性差异不是模型智能，而是 Agent 结构：工具让它可以『动手』，循环让它能『做→看→修正』直到完成。"},{"q":"Agent Loop 的核心循环顺序是？","opts":["看 → 做 → 想","想 → 做 → 看 → 再想","只做不看不回头","想 → 想 → 想"],"a":1,"explain":"标准 agent loop：决定下一步（想）→ 调用工具（做）→ 观察结果（看）→ 根据结果再决定下一步（再想），循环到目标达成。"},{"q":"MCP（Model Context Protocol）主要解决什么问题？","opts":["让模型跑得更快","统一 Agent 接入工具/数据源的接口标准，避免各家用私有协议","代替向量数据库","让模型更聪明"],"a":1,"explain":"MCP 是 Agent 与文件、数据库、浏览器等外部工具的标准化接入协议，一次接入、到处复用。"}],"lab":{"title":"Mini Lab：跑一次 Agent 循环","desc":"在上方循环图里，设一个任务（修 bug / 发邮件 / 整理数据），观察 Agent 每轮『想什么、调哪个工具、看到什么结果』，直到完成或需要你授权。","kind":"agent-loop"}},{"type":"connection","known":["Transformer：模型怎么生成内容","RAG：怎么让模型查资料","工具调用 Function Calling"],"learned":["Agent = 模型 + 工具 + 循环（想→做→看→再想）","它能拆目标、规划、调用工具、观察反馈、反复修正","关键工程点：Tool Use / Memory / Planning / Permission / MCP"],"next":"到这里，你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。想继续深入，建议顺着你的目标分支走：做产品学 LLM 应用与 RAG，写代码就进入 AI 编程（Agentic Coding / Claude Code）那一章。"}]}]},"lessonConceptMap":{"ai-what":["l00-ai-world"],"ai-ml-dl":["l00-ai-world"],"ai-apps":["l00-ai-world"],"ai-limits":["l00-ai-world"],"embedding":["l-embedding"],"vector":["l-embedding"],"cosine-similarity":["l-embedding"],"emb-vector-store":["l-embedding","l-rag"],"attention":["l-attention","l-transformer"],"qkv":["l-attention"],"multihead":["l-attention","l-transformer"],"attention-long":["l-attention"],"transformer":["l-transformer"],"position-enc":["l-transformer"],"rag-pain":["l-rag"],"rag-pipeline":["l-rag"],"chunking":["l-rag"],"vector-search":["l-rag"],"rerank":["l-rag"],"agent-intro":["l-agent"],"agent-loop":["l-agent"],"tool-use":["l-agent"],"agent-planning":["l-agent"],"agent-memory":["l-agent"],"agent-reflection":["l-agent"]}};
  var lessons = DATA.lessons, curriculum = DATA.curriculum;
  var lessonsByCat = DATA.lessonsByCat, lessonConceptMap = DATA.lessonConceptMap;
  var flagship = DATA.flagship || [];

  function getLesson(id) { return lessons[id] || null; }
  function getLessonsByCategory(catId) { return lessonsByCat[catId] || []; }
  function lessonForConcept(cid) { return lessonConceptMap[cid] || []; }
  function getCurriculumLessonMeta(id) {
    for (var ci = 0; ci < (curriculum.categories || []).length; ci++) {
      var cat = curriculum.categories[ci];
      for (var hi = 0; hi < (cat.chapters || []).length; hi++) {
        var ch = cat.chapters[hi];
        for (var li = 0; li < (ch.lessons || []).length; li++) {
          if (ch.lessons[li].id === id) return ch.lessons[li];
        }
      }
    }
    return null;
  }
  function readyLessons() { return Object.keys(lessons).map(function (id) { return lessons[id]; }); }
  function flagshipLessons() {
    var out = [];
    flagship.forEach(function (id) { if (lessons[id]) out.push(lessons[id]); });
    return out;
  }
  function flaggedMeta(id) { return getCurriculumLessonMeta(id); }

  var L = {
    version: DATA.version,
    builtAt: DATA.builtAt,
    curriculum: curriculum,
    lessonCount: DATA.lessonCount,
    flagship: flagship,
    lessons: lessons,
    byId: lessons,
    lessonsByCat: lessonsByCat,
    lessonConceptMap: lessonConceptMap,
    getLesson: getLesson,
    getLessonsByCategory: getLessonsByCategory,
    lessonForConcept: lessonForConcept,
    getCurriculumLessonMeta: getCurriculumLessonMeta,
    readyLessons: readyLessons,
    flagshipLessons: flagshipLessons,
    flaggedMeta: flaggedMeta
  };

  if (typeof window !== "undefined") window.LEARN = L;
  if (typeof module !== "undefined" && module.exports) module.exports = L;
})();